function classifyMarketResultV2({ url = '', title = '', snippet = '', query = '', lang = 'fr' } = {}) {
    const host = safeHostname(url);
    const path = safePath(url);
    const blob = `${host} ${title} ${snippet} ${path} ${query}`.toLowerCase();
    const baseType = classifyCompetitorType(url, title, snippet, lang);
    const commercialScore = commercialIntentScore(url, title, snippet);
    const blocked = isBlockedCompetitorUrl(url, title, snippet);
    const officialLike = isOfficialLikeCompetitor(url, title, snippet);
    const rejectionReason = competitorRejectionReason(url, title, snippet, commercialScore);
    const marketplace = /(amazon|fnac|cdiscount|jumia|noon|etsy|ebay|aliexpress|carrefour|walmart|bestbuy|marketplace)/i.test(`${host} ${blob}`);
    const social = SOCIAL_COMPETITOR_DOMAINS.some(domain => host.includes(domain));
    const labelsFor = (kind) => marketResultLabelsV2(kind, lang);

    if (!host) {
        const labels = labelsFor('market_source');
        return {
            isRealCompetitor: false,
            category: 'market_source',
            typeLabel: labels.typeLabel,
            role: labels.role,
            recommendedUse: labels.recommendedUse,
            sourceGroup: labels.sourceGroup,
            rejectionReason: 'invalid_url'
        };
    }

    if (social) {
        const labels = labelsFor('social_source');
        return {
            isRealCompetitor: false,
            category: 'social_source',
            typeLabel: labels.typeLabel,
            role: labels.role,
            recommendedUse: labels.recommendedUse,
            sourceGroup: labels.sourceGroup,
            rejectionReason: 'social_source'
        };
    }

    if (marketplace) {
        const labels = labelsFor('marketplace');
        return {
            isRealCompetitor: false,
            category: 'marketplace',
            typeLabel: labels.typeLabel,
            role: labels.role,
            recommendedUse: labels.recommendedUse,
            sourceGroup: labels.sourceGroup,
            rejectionReason: 'marketplace_not_direct'
        };
    }

    if (blocked) {
        const labels = labelsFor('market_source');
        return {
            isRealCompetitor: false,
            category: 'market_source',
            typeLabel: baseType.type || labels.typeLabel,
            role: labels.role,
            recommendedUse: labels.recommendedUse,
            sourceGroup: labels.sourceGroup,
            rejectionReason: rejectionReason || 'informational_source'
        };
    }

    if (commercialScore >= 25 && officialLike) {
        const labels = labelsFor('direct_competitor');
        return {
            isRealCompetitor: true,
            category: baseType.competitorType || 'website',
            typeLabel: baseType.type || labels.typeLabel,
            role: labels.role,
            recommendedUse: labels.recommendedUse,
            sourceGroup: labels.sourceGroup,
            rejectionReason: null
        };
    }

    if (commercialScore >= 15 && officialLike) {
        const labels = labelsFor('benchmark_regional');
        return {
            isRealCompetitor: false,
            category: baseType.competitorType || 'website',
            typeLabel: baseType.type || labels.typeLabel,
            role: labels.role,
            recommendedUse: labels.recommendedUse,
            sourceGroup: labels.sourceGroup,
            rejectionReason: 'benchmark_only'
        };
    }

    const labels = labelsFor('market_source');
    return {
        isRealCompetitor: false,
        category: baseType.competitorType || 'market_source',
        typeLabel: baseType.type || labels.typeLabel,
        role: labels.role,
        recommendedUse: labels.recommendedUse,
        sourceGroup: labels.sourceGroup,
        rejectionReason: rejectionReason || 'insufficient_commercial_signals'
    };
}

function competitorGeoPhraseMatch(text = '', phrase = '') {
    const normalize = value => String(value || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase()
        .replace(/\s+/g, ' ')
        .trim();
    const haystack = normalize(text);
    const needle = normalize(phrase);
    if (!haystack || !needle) return false;
    const escaped = needle.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    return new RegExp(`(^|[^\\p{L}\\p{N}])${escaped}(?=$|[^\\p{L}\\p{N}])`, 'u').test(haystack);
}

function competitorGeoMismatchNote(query = '', geo = '', lang = 'fr') {
    const rawQuery = String(query || '').toLowerCase();
    const geoKey = String(geo || '').trim().toLowerCase();
    if (!rawQuery || !geoKey) return '';

    const aliases = Object.fromEntries(
        Object.values(COMPETITOR_STRICT_GEO_RULES).map(rule => [rule.country, rule.aliases])
    );
    const selectedGeo = resolveSerpGeo(geoKey);
    const selectedCountry = COMPETITOR_STRICT_GEO_RULES[String(selectedGeo?.gl || '').toLowerCase()]?.country || geoKey;

    const mentioned = Object.keys(aliases).find((country) => aliases[country].some((token) => competitorGeoPhraseMatch(rawQuery, token)));
    if (!mentioned) return '';

    if (geoKey === 'global english') {
        return lang === 'ar'
            ? `\u062a\u062d\u062a\u0648\u064a \u0627\u0644\u0639\u0628\u0627\u0631\u0629 \u0639\u0644\u0649 ${localizeCompetitorMarketName(mentioned, 'ar')}\u060c \u0644\u0643\u0646 \u0627\u0644\u0627\u0633\u062a\u0647\u062f\u0627\u0641 \u0627\u0644\u0645\u062d\u062f\u062f \u0647\u0648 \u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629 \u0627\u0644\u0639\u0627\u0644\u0645\u064a\u0629. \u0641\u0633\u0631 \u0627\u0644\u0646\u062a\u0627\u0626\u062c \u0643\u0625\u0634\u0627\u0631\u0627\u062a \u0639\u0627\u0644\u0645\u064a\u0629 \u0645\u0639 \u062d\u0627\u062c\u0629 \u0625\u0644\u0649 \u062a\u062d\u0642\u0642 \u0645\u062d\u0644\u064a.`
            : lang === 'en'
                ? `The query mentions ${localizeCompetitorMarketName(mentioned, 'en')}, but the selected targeting is Global English. Treat the findings as global signals and verify locally.`
                : `La requête mentionne ${localizeCompetitorMarketName(mentioned, 'fr')}, mais le ciblage sélectionné est Global English. Interprétez les résultats comme des signaux globaux avec vérification locale nécessaire.`;
    }

    if (mentioned === selectedCountry) return '';

    return lang === 'ar'
        ? `\u062a\u0630\u0643\u0631 \u0627\u0644\u0639\u0628\u0627\u0631\u0629 ${localizeCompetitorMarketName(mentioned, 'ar')}\u060c \u0628\u064a\u0646\u0645\u0627 \u0627\u0644\u0633\u0648\u0642 \u0627\u0644\u0645\u062d\u062f\u062f \u0647\u0648 ${localizeCompetitorMarketName(geo, 'ar')}. \u0627\u0644\u0646\u062a\u064a\u062c\u0629 \u062a\u062d\u062a\u0627\u062c \u0642\u0631\u0627\u0621\u0629 \u0645\u062d\u0644\u064a\u0629 \u0645\u0646\u0641\u0635\u0644\u0629.`
        : lang === 'en'
            ? `The query mentions ${localizeCompetitorMarketName(mentioned, 'en')}, while the selected market is ${localizeCompetitorMarketName(geo, 'en')}. Review the output with local validation.`
            : `La requête mentionne ${localizeCompetitorMarketName(mentioned, 'fr')}, alors que le marché ciblé est ${localizeCompetitorMarketName(geo, 'fr')}. Relisez la sortie avec validation locale.`;
}

function geoBoostScore(rawUrl = '', geoData = {}, title = '', snippet = '') {
    const host = safeHostname(rawUrl);
    const blob = `${host} ${title} ${snippet}`.toLowerCase();
    const gl = String(geoData?.gl || '').toLowerCase();
    const location = String(geoData?.location || '').toLowerCase();

    let score = 0;

    if (gl === 'ma' && /\\.ma\\b|morocco|maroc/.test(blob)) score += 40;
    if (gl === 'sa' && /\\.sa\\b|saudi|arabie saoudite|riyadh|jeddah/.test(blob)) score += 40;
    if (gl === 'ae' && /\\.ae\\b|uae|emirates|dubai|abu dhabi/.test(blob)) score += 40;
    if (gl === 'fr' && /\\.fr\\b|france|paris|lyon/.test(blob)) score += 40;
    if (gl === 'dz' && /\\.dz\\b|algeria|algérie|alger/.test(blob)) score += 40;
    if (gl === 'tn' && /\\.tn\\b|tunisia|tunisie|tunis/.test(blob)) score += 40;
    if (gl === 'eg' && /\\.eg\\b|egypt|egypte|cairo/.test(blob)) score += 40;

    if (location && blob.includes(location)) score += 20;

    return score;
}

function geoMatchDetailsV2(rawUrl = '', geoData = {}, title = '', snippet = '') {
    const host = safeHostname(rawUrl);
    const blob = `${host} ${title} ${snippet}`.toLowerCase();
    const gl = String(geoData?.gl || '').toLowerCase();
    const location = String(geoData?.location || '').toLowerCase();
    const matchedTerms = [];
    let score = 0;

    if (gl && host.endsWith(`.${gl}`)) {
        score += 45;
        matchedTerms.push(`tld:.${gl}`);
    }

    const aliasesByGl = {
        ma: ['morocco', 'maroc', 'casablanca', 'rabat', 'marrakech', 'tanger', 'tangier', 'fes', 'fez', 'agadir', 'meknes'],
        sa: ['saudi', 'arabie saoudite', 'riyadh', 'jeddah', 'dammam', 'mecca', 'medina'],
        ae: ['uae', 'emirates', 'dubai', 'abu dhabi', 'sharjah'],
        fr: ['france', 'paris', 'lyon', 'marseille', 'toulouse'],
        dz: ['algeria', 'algerie', 'alger', 'oran', 'constantine'],
        tn: ['tunisia', 'tunisie', 'tunis', 'sfax'],
        eg: ['egypt', 'egypte', 'cairo', 'alexandria', 'giza']
    };

    for (const alias of aliasesByGl[gl] || []) {
        if (blob.includes(alias)) {
            score += 12;
            matchedTerms.push(alias);
        }
    }

    const locationTokens = location
        .split(/[\s,]+/)
        .map(x => x.trim())
        .filter(x => x.length >= 4 && !['morocco', 'france', 'algeria', 'tunisia', 'egypt', 'saudi', 'arabia'].includes(x));

    for (const token of locationTokens) {
        if (blob.includes(token)) {
            score += 15;
            matchedTerms.push(`loc:${token}`);
        }
    }

    return {
        score: Math.min(score, 80),
        matchedTerms: [...new Set(matchedTerms)].slice(0, 8),
        geoTarget: geoData?.location || null,
        gl
    };
}

const COMPETITOR_STRICT_GEO_RULES = {
    ma: { country: 'morocco', tlds: ['.ma'], aliases: ['morocco', 'maroc', 'casablanca', 'rabat', 'marrakech', 'tanger', 'agadir', '\u0627\u0644\u0645\u063a\u0631\u0628'] },
    ly: { country: 'libya', tlds: ['.ly'], aliases: ['libya', 'libye', 'tripoli', 'benghazi', 'misrata', '\u0644\u064a\u0628\u064a\u0627', '\u0637\u0631\u0627\u0628\u0644\u0633', '\u0628\u0646\u063a\u0627\u0632\u064a'] },
    tn: { country: 'tunisia', tlds: ['.tn'], aliases: ['tunisia', 'tunisie', 'tunis', 'sfax', '\u062a\u0648\u0646\u0633'] },
    dz: { country: 'algeria', tlds: ['.dz'], aliases: ['algeria', 'algerie', 'alger', 'oran', 'constantine', '\u0627\u0644\u062c\u0632\u0627\u0626\u0631'] },
    eg: { country: 'egypt', tlds: ['.eg'], aliases: ['egypt', 'egypte', 'cairo', 'alexandria', 'giza', '\u0645\u0635\u0631', '\u0627\u0644\u0642\u0627\u0647\u0631\u0629'] },
    sa: { country: 'saudi arabia', tlds: ['.sa'], aliases: ['saudi arabia', 'saudi', 'arabie saoudite', 'riyadh', 'jeddah', 'dammam', '\u0627\u0644\u0633\u0639\u0648\u062f\u064a\u0629'] },
    ae: { country: 'united arab emirates', tlds: ['.ae'], aliases: ['united arab emirates', 'uae', 'emirates', 'dubai', 'abu dhabi', 'sharjah', '\u0627\u0644\u0625\u0645\u0627\u0631\u0627\u062a'] },
    qa: { country: 'qatar', tlds: ['.qa'], aliases: ['qatar', 'doha', '\u0642\u0637\u0631', '\u0627\u0644\u062f\u0648\u062d\u0629'] },
    kw: { country: 'kuwait', tlds: ['.kw'], aliases: ['kuwait', 'koweit', '\u0627\u0644\u0643\u0648\u064a\u062a'] },
    bh: { country: 'bahrain', tlds: ['.bh'], aliases: ['bahrain', 'bahrein', 'manama', '\u0627\u0644\u0628\u062d\u0631\u064a\u0646', '\u0627\u0644\u0645\u0646\u0627\u0645\u0629'] },
    om: { country: 'oman', tlds: ['.om'], aliases: ['oman', 'muscat', 'mascate', '\u0639\u0645\u0627\u0646', '\u0645\u0633\u0642\u0637'] },
    jo: { country: 'jordan', tlds: ['.jo'], aliases: ['jordan', 'jordanie', 'amman', '\u0627\u0644\u0623\u0631\u062f\u0646'] },
    lb: { country: 'lebanon', tlds: ['.lb'], aliases: ['lebanon', 'liban', 'beirut', 'beyrouth', '\u0644\u0628\u0646\u0627\u0646', '\u0628\u064a\u0631\u0648\u062a'] },
    fr: { country: 'france', tlds: ['.fr'], aliases: ['france', 'paris', 'lyon', 'marseille', 'toulouse', '\u0641\u0631\u0646\u0633\u0627'] },
    us: { country: 'united states', tlds: ['.us'], aliases: ['united states', 'united states of america', 'usa', 'u.s.a', '\u0627\u0644\u0648\u0644\u0627\u064a\u0627\u062a \u0627\u0644\u0645\u062a\u062d\u062f\u0629'] }
};

function geoMatchDetailsStrictV3(rawUrl = '', geoData = {}, title = '', snippet = '') {
    const host = safeHostname(rawUrl);
    const blob = `${host} ${title || ''} ${snippet || ''}`;
    const gl = String(geoData?.gl || '').toLowerCase();
    const location = String(geoData?.location || '');
    const isGlobal = location.toLowerCase() === 'global english';
    const rule = COMPETITOR_STRICT_GEO_RULES[gl] || null;
    const matchedTerms = [];
    let score = 0;

    for (const tld of rule?.tlds || []) {
        if (host.endsWith(tld)) {
            score += 45;
            matchedTerms.push(`tld:${tld}`);
        }
    }
    for (const alias of rule?.aliases || []) {
        if (competitorGeoPhraseMatch(blob, alias)) {
            score += 12;
            matchedTerms.push(alias);
        }
    }
    if (location && competitorGeoPhraseMatch(blob, location)) {
        score += 20;
        matchedTerms.push(`location:${location.toLowerCase()}`);
    }

    return {
        score: Math.min(score, 80),
        matchedTerms: [...new Set(matchedTerms)].slice(0, 8),
        geoTarget: location || null,
        gl,
        country: rule?.country || (isGlobal ? 'global english' : null),
        strictMatched: isGlobal || score >= 12
    };
}

function classifyCompetitorGeoTier(rawUrl = '', geoData = {}, title = '', snippet = '', options = {}) {
    const match = geoMatchDetailsStrictV3(rawUrl, geoData, title, snippet);
    const targetGl = String(geoData?.gl || '').toLowerCase();
    const targetLocation = String(geoData?.location || '').toLowerCase();
    const isGlobal = targetLocation === 'global english';
    if (isGlobal || match.strictMatched) {
        return { ...match, tier: 'LOCAL_CONFIRMED', local: true, foreignConflict: null };
    }

    const host = safeHostname(rawUrl);
    const blob = `${host} ${title || ''} ${snippet || ''}`;
    let foreignConflict = null;
    for (const [gl, rule] of Object.entries(COMPETITOR_STRICT_GEO_RULES)) {
        if (gl === targetGl) continue;
        const tldMatch = (rule.tlds || []).find(tld => host.endsWith(tld));
        const aliasMatch = (rule.aliases || []).find(alias => competitorGeoPhraseMatch(blob, alias));
        if (tldMatch || aliasMatch) {
            foreignConflict = {
                gl,
                country: rule.country,
                signal: tldMatch ? `tld:${tldMatch}` : aliasMatch
            };
            break;
        }
    }

    if (foreignConflict) {
        return { ...match, tier: 'FOREIGN_BENCHMARK', local: false, foreignConflict };
    }
    if (options.fromTargetedSerp !== false && isPublicHttpUrl(rawUrl)) {
        return {
            ...match,
            tier: 'LOCAL_PROBABLE',
            local: true,
            foreignConflict: null,
            matchedTerms: [...new Set([...(match.matchedTerms || []), `serp:${targetGl || 'target'}`])]
        };
    }
    return { ...match, tier: 'UNCONFIRMED', local: false, foreignConflict: null };
}

const COMPETITOR_QUERY_LOCALIZATION_CACHE = new Map();

function detectCompetitorQueryLanguage(value = '') {
    const text = String(value || '').trim().toLowerCase();
    if (!text) return null;
    if (/[\u0600-\u06ff]/.test(text)) return 'ar';
    if (/[àâçéèêëîïôùûüÿœ]/i.test(text) || /\b(?:agence|logiciel|maroc|libye|tunisie|alg[eé]rie|prix|acheter|concurrent|march[eé]|service|formation)\b/i.test(text)) return 'fr';
    if (/\b(?:agency|software|market|competitor|pricing|buy|service|training|united states|saudi arabia)\b/i.test(text)) return 'en';
    return null;
}

function fallbackCompetitorQueryTranslation(value = '', targetLang = 'fr') {
    const source = String(value || '').trim();
    const normalized = source.toLowerCase();
    const exact = {
        ar: {
            'agence marketing ia': '\u0648\u0643\u0627\u0644\u0629 \u062a\u0633\u0648\u064a\u0642 \u0628\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a',
            'saas marketing maroc': '\u0628\u0631\u0645\u062c\u064a\u0627\u062a \u0627\u0644\u062a\u0633\u0648\u064a\u0642 \u0643\u062e\u062f\u0645\u0629 \u0641\u064a \u0627\u0644\u0645\u063a\u0631\u0628',
            'logiciel de gestion et spy des concurrents': '\u0628\u0631\u0646\u0627\u0645\u062c \u0644\u0625\u062f\u0627\u0631\u0629 \u0648\u0645\u0631\u0627\u0642\u0628\u0629 \u0627\u0644\u0645\u0646\u0627\u0641\u0633\u064a\u0646'
        },
        fr: {
            'ai marketing agency': 'agence marketing IA',
            'competitor intelligence software': 'logiciel de veille concurrentielle'
        },
        en: {
            'agence marketing ia': 'AI marketing agency',
            'logiciel de veille concurrentielle': 'competitor intelligence software'
        }
    };
    if (exact[targetLang]?.[normalized]) return exact[targetLang][normalized];
    return source;
}

async function localizeCompetitorQueryForAnalysis(value = '', targetLang = 'fr') {
    const originalQuery = String(value || '').replace(/\s+/g, ' ').trim();
    const safeTarget = ['fr', 'en', 'ar'].includes(targetLang) ? targetLang : 'fr';
    const cacheKey = `${safeTarget}:${originalQuery.toLowerCase()}`;
    const cached = COMPETITOR_QUERY_LOCALIZATION_CACHE.get(cacheKey);
    if (cached) return cached;
    const detectedLang = detectCompetitorQueryLanguage(originalQuery);
    const isUrl = /^https?:\/\//i.test(originalQuery);
    let localizedQuery = originalQuery;
    let source = 'original';

    if (!isUrl && originalQuery && detectedLang !== safeTarget) {
        try {
            const response = await axios.get('https://translate.googleapis.com/translate_a/single', {
                params: { client: 'gtx', sl: 'auto', tl: safeTarget, dt: 't', q: originalQuery },
                timeout: 3500,
                maxContentLength: 120000
            });
            const translated = Array.isArray(response.data?.[0])
                ? response.data[0].map(part => Array.isArray(part) ? part[0] : '').filter(Boolean).join('')
                : '';
            if (translated && translated.trim().length >= 2) {
                localizedQuery = translated.replace(/\s+/g, ' ').trim();
                source = 'translation';
            }
        } catch (error) {
            console.warn(`[WarRoom-V10.0] Query translation fallback: ${error.message}`);
        }
        if (localizedQuery === originalQuery) {
            localizedQuery = fallbackCompetitorQueryTranslation(originalQuery, safeTarget);
            source = localizedQuery === originalQuery ? 'original-fallback' : 'glossary-fallback';
        }
    }

    const result = {
        originalQuery,
        localizedQuery,
        detectedLang,
        targetLang: safeTarget,
        source,
        searchVariants: [...new Set([originalQuery, localizedQuery].filter(Boolean))]
    };
    COMPETITOR_QUERY_LOCALIZATION_CACHE.set(cacheKey, result);
    if (COMPETITOR_QUERY_LOCALIZATION_CACHE.size > 250) {
        COMPETITOR_QUERY_LOCALIZATION_CACHE.delete(COMPETITOR_QUERY_LOCALIZATION_CACHE.keys().next().value);
    }
    return result;
}

const COMPETITOR_BUSINESS_CACHE = new Map();
const COMPETITOR_BUSINESS_CACHE_TTL = 12 * 60 * 60 * 1000;

function compactBusinessText(value, max = 220) {
    return String(value || '').replace(/\s+/g, ' ').trim().slice(0, max);
}

function cleanCompetitorBusinessText(value, max = 260) {
    const iconWords = /\b(?:arrow_right_alt|arrow_forward|location_on|open_in_new|chevron_right|expand_more|menu|search|close|home|shopping_cart|person|login|logout|favorite|share|more_vert)\b/gi;
    const source = String(value || '');
    if (/(?:Ã.|Ø.|Ù.|â.){2,}/.test(source)) return '';
    return source
        .replace(/<[^>]*>/g, ' ')
        .replace(/\b(?:class|style|onclick|aria-label|data-[\w-]+)\s*=\s*["'][^"']*["']/gi, ' ')
        .replace(iconWords, ' ')
        .replace(/\bCHAPITRE\b/gi, ' ')
        .replace(/\s*([|·•])\s*/g, ' · ')
        .replace(/(?:\s*·\s*){2,}/g, ' · ')
        .replace(/\s+/g, ' ')
        .trim()
        .slice(0, max);
}

function dedupeBusinessInsights(items = [], limit = 5) {
    const accepted = [];
    const fingerprints = [];
    for (const item of Array.isArray(items) ? items : []) {
        const clean = cleanCompetitorBusinessText(
            typeof item === 'string' ? item : item?.action || item?.reason || item?.title,
            320
        );
        if (!clean) continue;
        const fingerprint = clean.toLowerCase()
            .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
            .replace(/[^\p{L}\p{N}\s]/gu, ' ')
            .replace(/\b(?:les|des|une|pour|avec|dans|the|and|with|that|this|\u0639\u0644\u0649|\u0641\u064a|\u0645\u0646|\u0645\u0639)\b/gu, ' ')
            .replace(/\s+/g, ' ')
            .trim();
        if (!fingerprint || fingerprints.some(x => x.includes(fingerprint) || fingerprint.includes(x))) continue;
        fingerprints.push(fingerprint);
        accepted.push(typeof item === 'string'
            ? clean
            : { ...item, action: item.action ? clean : item.action, reason: item.reason ? clean : item.reason });
        if (accepted.length >= limit) break;
    }
    return accepted;
}

function competitorConfidenceExplanation(confidence = 'LOW', lang = 'fr') {
    if (confidence === 'HIGH') {
        return lang === 'ar'
            ? '\u0627\u0644\u062b\u0642\u0629 \u0645\u0631\u062a\u0641\u0639\u0629: \u062a\u0645 \u0627\u0633\u062a\u0643\u0634\u0627\u0641 \u0627\u0644\u0635\u0641\u062d\u0629\u060c \u0648\u0627\u0644\u0639\u0631\u0636 \u0648\u0627\u0636\u062d\u060c \u0648\u062a\u0645 \u0631\u0635\u062f \u0625\u0634\u0627\u0631\u0627\u062a \u062a\u062c\u0627\u0631\u064a\u0629 \u0648\u0623\u062f\u0644\u0629 \u0645\u0631\u0626\u064a\u0629.'
            : lang === 'en'
                ? 'High confidence: the page was explored, the offer is clear, and several commercial signals and proofs are visible.'
                : 'Confiance élevée : page explorée, offre claire, signaux commerciaux visibles et plusieurs preuves détectées.';
    }
    if (confidence === 'MEDIUM') {
        return lang === 'ar'
            ? '\u0627\u0644\u062b\u0642\u0629 \u0645\u062a\u0648\u0633\u0637\u0629: \u062a\u0645 \u0631\u0635\u062f \u0625\u0634\u0627\u0631\u0627\u062a \u0641\u064a \u0627\u0644\u0635\u0641\u062d\u0629\u060c \u0644\u0643\u0646 \u0628\u0639\u0636 \u0627\u0644\u0623\u0633\u0639\u0627\u0631 \u0623\u0648 \u0623\u062f\u0644\u0629 \u0627\u0644\u0639\u0645\u0644\u0627\u0621 \u0645\u0627 \u0632\u0627\u0644\u062a \u063a\u064a\u0631 \u0648\u0627\u0636\u062d\u0629.'
            : lang === 'en'
                ? 'Medium confidence: page signals were observed, but some pricing or customer proof remains unclear.'
                : 'Confiance moyenne : signaux observés sur la page, mais certaines données tarifaires ou preuves clients restent peu claires.';
    }
    return lang === 'ar'
        ? '\u0627\u0644\u062b\u0642\u0629 \u0636\u0639\u064a\u0641\u0629: \u062a\u0645 \u0631\u0635\u062f \u0627\u0644\u0646\u062a\u064a\u062c\u0629\u060c \u0644\u0643\u0646 \u0644\u0645 \u064a\u062a\u0645 \u062a\u0623\u0643\u064a\u062f \u0627\u0644\u062a\u0648\u0641\u0631 \u0627\u0644\u0645\u062d\u0644\u064a \u0623\u0648 \u0627\u0633\u062a\u062e\u0631\u0627\u062c \u0623\u062f\u0644\u0629 \u0643\u0627\u0641\u064a\u0629.'
        : lang === 'en'
            ? 'Low confidence: the result was detected, but local availability or sufficient page evidence could not be confirmed.'
            : 'Confiance faible : résultat détecté, mais page peu explorée ou disponibilité locale non confirmée.';
}

function competitorBusinessLabels(lang = 'fr') {
    if (lang === 'ar') return {
        fallbackSell: 'عرض تجاري تم رصده على هذه الطلبات ويحتاج إلى توصيف أوضح.',
        weakTrust: 'عناصر الثقة أو الضمان لا تظهر بوضوح في الصفحة المعاينة.',
        weakPrice: 'السعر أو شروط الدفع غير مؤكدة بما يكفي في الصفحة المعاينة.',
        weakDelivery: 'معلومات التوصيل أو الإرجاع أو التنفيذ ليست واضحة بما يكفي في الصفحة المعاينة.',
        attack: 'اجعل عرضك أوضح، أسهل مقارنة، وأكثر قابلية للتحقق.',
        proof: 'أضف أدلة عملاء، شروطا واضحة، وعنصر طمأنة يمكن التحقق منه.'
    };
    if (lang === 'en') return {
        fallbackSell: 'A commercial offer was observed on this demand and needs clearer qualification.',
        weakTrust: 'Trust elements or guarantees are not clearly visible on the inspected page.',
        weakPrice: 'Price or payment terms are not confirmed clearly enough on the inspected page.',
        weakDelivery: 'Delivery, returns, or execution details are not clear enough on the inspected page.',
        attack: 'Make your offer clearer, easier to compare, and easier to verify.',
        proof: 'Add customer proof, clear terms, and one verifiable reassurance element.'
    };
    return {
        fallbackSell: 'Une offre commerciale a été repérée sur cette demande et doit être mieux qualifiée.',
        weakTrust: 'Les éléments de confiance ou de garantie ne sont pas assez visibles sur la page analysée.',
        weakPrice: 'Le prix ou les conditions de paiement ne sont pas confirmés assez clairement sur la page analysée.',
        weakDelivery: 'Les informations de livraison, de retour ou d’exécution ne sont pas assez claires sur la page analysée.',
        attack: "Rends l’offre plus claire, plus simple à comparer et plus facile à vérifier.",
        proof: 'Ajoute des preuves clients, des conditions claires et un élément de réassurance vérifiable.'
    };
}
function localizeCompetitorMarketName(geo = '', lang = 'fr') {
    const locale = ['fr', 'en', 'ar'].includes(lang) ? lang : 'fr';
    const raw = String(geo || '').trim();
    const key = raw.toLowerCase();
    const markets = {
        'morocco': { fr: 'Maroc', en: 'Morocco', ar: '\u0627\u0644\u0645\u063A\u0631\u0628' },
        'libya': { fr: 'Libye', en: 'Libya', ar: '\u0644\u064A\u0628\u064A\u0627' },
        'tunisia': { fr: 'Tunisie', en: 'Tunisia', ar: '\u062A\u0648\u0646\u0633' },
        'algeria': { fr: 'Alg\u00E9rie', en: 'Algeria', ar: '\u0627\u0644\u062C\u0632\u0627\u0626\u0631' },
        'egypt': { fr: '\u00C9gypte', en: 'Egypt', ar: '\u0645\u0635\u0631' },
        'saudi arabia': { fr: 'Arabie saoudite', en: 'Saudi Arabia', ar: '\u0627\u0644\u0633\u0639\u0648\u062F\u064A\u0629' },
        'united arab emirates': { fr: '\u00C9mirats arabes unis', en: 'United Arab Emirates', ar: '\u0627\u0644\u0625\u0645\u0627\u0631\u0627\u062A' },
        'qatar': { fr: 'Qatar', en: 'Qatar', ar: '\u0642\u0637\u0631' },
        'kuwait': { fr: 'Kowe\u00EFt', en: 'Kuwait', ar: '\u0627\u0644\u0643\u0648\u064A\u062A' },
        'bahrain': { fr: 'Bahre\u00EFn', en: 'Bahrain', ar: '\u0627\u0644\u0628\u062D\u0631\u064A\u0646' },
        'oman': { fr: 'Oman', en: 'Oman', ar: '\u0639\u0645\u0627\u0646' },
        'jordan': { fr: 'Jordanie', en: 'Jordan', ar: '\u0627\u0644\u0623\u0631\u062F\u0646' },
        'lebanon': { fr: 'Liban', en: 'Lebanon', ar: '\u0644\u0628\u0646\u0627\u0646' },
        'france': { fr: 'France', en: 'France', ar: '\u0641\u0631\u0646\u0633\u0627' },
        'united states': { fr: '\u00C9tats-Unis', en: 'United States', ar: '\u0627\u0644\u0648\u0644\u0627\u064A\u0627\u062A \u0627\u0644\u0645\u062A\u062D\u062F\u0629' },
        'global english': { fr: 'March\u00E9 global anglophone', en: 'Global English', ar: '\u0627\u0644\u0625\u0646\u062C\u0644\u064A\u0632\u064A\u0629 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629' }
    };
    const found = markets[key];
    if (found) return found[locale] || found.fr;
    if (!raw) return locale === 'ar' ? '\u0627\u0644\u0633\u0648\u0642 \u0627\u0644\u0645\u0633\u062A\u0647\u062F\u0641' : locale === 'en' ? 'target market' : 'march\u00E9 cible';
    return raw;
}
function competitorMarketPhrase(geo = '', lang = 'fr') {
    const market = localizeCompetitorMarketName(geo, lang);
    if (lang === 'ar') return `\u0641\u064a \u0633\u0648\u0642 ${market}`;
    if (lang === 'en') return `for the ${market} market`;
    return `pour le march\u00E9 ${market}`;
}
async function fetchCompetitorBusinessProfile(competitor = {}, lang = 'fr') {
    const labels = competitorBusinessLabels(lang);
    const cacheKey = String(competitor.url || competitor.domain || '').toLowerCase();
    const cached = COMPETITOR_BUSINESS_CACHE.get(cacheKey);
    if (cached && Date.now() - cached.savedAt < COMPETITOR_BUSINESS_CACHE_TTL) return cached.value;

    const fallback = {
        // A SERP title/snippet is evidence about the page, not a promise we can
        // safely attribute to the business. Keep the fallback factual and sparse.
        whatTheySell: compactBusinessText(competitor.snippet, 180),
        primaryPromise: '',
        observedStrengths: [],
        structuralStrengths: [],
        productSignals: compactBusinessText(competitor.snippet, 180) ? [compactBusinessText(competitor.snippet, 180)] : [],
        deducedWeaknesses: [],
        missingProofs: [],
        attackAngle: '',
        evidenceLinks: [competitor.url].filter(Boolean),
        confidence: 'LOW',
        observed: false,
        signals: {}
    };
    if (!competitor.url || !isPublicHttpUrl(competitor.url)) return fallback;

    try {
        const requestOptions = {
            timeout: 3500,
            maxRedirects: 3,
            maxContentLength: 900000,
            headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/124.0 Safari/537.36' }
        };
        const originUrl = new URL(competitor.url).origin + '/';
        const requests = [axios.get(competitor.url, requestOptions)];
        if (originUrl !== competitor.url) requests.push(axios.get(originUrl, requestOptions));
        const fetched = await Promise.allSettled(requests);
        let pageHtml = fetched[0]?.status === 'fulfilled' && typeof fetched[0].value?.data === 'string'
            ? fetched[0].value.data : '';
        let homeHtml = fetched[1]?.status === 'fulfilled' && typeof fetched[1].value?.data === 'string'
            ? fetched[1].value.data : pageHtml;
        if (!homeHtml && competitor.position === 1 && process.env.SCRAPEDOTOKEN) {
            try {
                const proxy = await axios.get('https://api.scrape.do/', {
                    params: { token: process.env.SCRAPEDOTOKEN, url: originUrl },
                    timeout: 5000,
                    maxContentLength: 900000
                });
                homeHtml = typeof proxy.data === 'string' ? proxy.data : '';
            } catch (proxyError) {
                console.warn(`[CompetitorBusiness] leader fallback blocked: ${proxyError.message}`);
            }
        }
        if (!pageHtml && !homeHtml) return fallback;

        const $ = cheerio.load(pageHtml || homeHtml);
        const $home = cheerio.load(homeHtml || pageHtml);
        $('script,style,noscript,svg').remove();
        $home('script,style,noscript,svg').remove();
        const body = compactBusinessText($('body').text(), 9000).toLowerCase();
        const brandBody = compactBusinessText($home('body').text(), 12000).toLowerCase();
        const headings = $('h1,h2').map((_, el) => compactBusinessText($(el).text(), 180)).get().filter(Boolean);
        const ctas = $('a,button').map((_, el) => compactBusinessText($(el).text(), 90)).get()
            .filter(text => /buy|shop|order|book|demo|trial|contact|quote|pricing|price|acheter|commander|reserver|devis|tarif|prix|contact|essai|اطلب|اشتر|تواصل|السعر/.test(text.toLowerCase()))
            .slice(0, 8);
        const pageHost = safeHostname(competitor.url);
        const importantLinks = $home('a[href]').map((_, el) => {
            try {
                const href = new URL($(el).attr('href'), competitor.url).href;
                const label = compactBusinessText($(el).text(), 100);
                return safeHostname(href) === pageHost && /pricing|price|tarif|prix|service|solution|product|produit|offer|offre|guarantee|garantie|delivery|livraison|return|retour|case|client|testimonial|avis/.test(`${href} ${label}`.toLowerCase())
                    ? { url: href, label: label || href } : null;
            } catch { return null; }
        }).get().filter(Boolean);
        const evidenceLinks = [...new Map(
            [{ url: originUrl, label: competitor.domain }, { url: competitor.url, label: competitor.title }, ...importantLinks].map(x => [x.url, x])
        ).values()].slice(0, 8);

        const signals = {
            hasPrice: /(?:[$€£]|mad|dh|usd|eur)\s?\d|\d[\d\s.,]*(?:[$€£]|mad|dh|usd|eur)|pricing|tarif|prix/.test(body),
            hasGuarantee: /guarantee|garantie|satisfait ou rembourse|money back|ضمان/.test(body),
            hasDelivery: /delivery|shipping|livraison|expedition|توصيل|شحن/.test(body),
            hasReturns: /return|refund|retour|remboursement|إرجاع|استرجاع/.test(body),
            hasReviews: /testimonial|review|rating|avis client|temoignage|تقييم|آراء/.test(body),
            hasContact: /contact|whatsapp|tel:|mailto:|demo|devis|تواصل|واتساب/.test(body),
            hasCoverage: /countries|country|pays|europe|worldwide|international|maroc|morocco|دول|بلدان/.test(body),
            hasFaq: /faq|frequently asked|questions frequentes|الأسئلة الشائعة/.test(body),
            ctaCount: ctas.length,
            hasMarketplaceModel: /marketplace|vendeur|seller|sell on|devenir vendeur|boutiques|stores|categories|catégories/.test(brandBody),
            hasBroadCatalog: $home('a[href]').length >= 80 || /categories|catégories|toutes les boutiques|all products|nos produits/.test(brandBody),
            hasOnSiteSearch: $home('input[type="search"],form[action*="search"],input[name*="search"],input[placeholder*="recher"]').length > 0,
            hasAccountJourney: /mon compte|my account|login|connexion|sign in|create account/.test(brandBody),
            hasPaymentOptions: /paiement|payment|cash on delivery|cod|carte bancaire|visa|mastercard|paypal/.test(brandBody),
            brandHasDelivery: /delivery|shipping|livraison|expedition/.test(brandBody),
            brandHasReturns: /return|refund|retour|remboursement/.test(brandBody),
            hasMobileApp: /app store|google play|application mobile|mobile app/.test(brandBody),
            hasLocalPresence: /maroc|morocco|casablanca|rabat|livraison au maroc/.test(brandBody) || safeHostname(originUrl).endsWith('.ma'),
            internalLinkCount: $home('a[href]').length
        };
        const productSignals = [];
        if (signals.hasPrice) productSignals.push(lang === 'ar' ? 'يعرض السعر أو شروط الدفع على العرض' : lang === 'en' ? 'Displays pricing or payment terms on the offer' : "Affiche le prix ou les conditions de paiement de l'offre");
        if (signals.hasReviews) productSignals.push(lang === 'ar' ? 'يعرض آراء عملاء على العرض' : lang === 'en' ? 'Displays customer reviews on the offer' : "Affiche des avis client sur l'offre");
        if (signals.hasGuarantee) productSignals.push(lang === 'ar' ? 'يذكر ضمانا على العرض' : lang === 'en' ? 'Mentions a guarantee on the offer' : "Mentionne une garantie sur l'offre");

        const structuralStrengths = [];
        if (signals.hasMarketplaceModel) structuralStrengths.push(lang === 'ar' ? 'نموذج سوق يجمع عدة بائعين وعروضا في مكان واحد' : lang === 'en' ? 'Marketplace model aggregating multiple sellers and offers' : 'Modele marketplace reunissant plusieurs vendeurs et offres');
        if (signals.hasBroadCatalog) structuralStrengths.push(lang === 'ar' ? 'كتالوج واسع يسهل المقارنة ويغطي طلبات متعددة' : lang === 'en' ? 'Broad catalogue enabling comparison across many needs' : 'Catalogue large facilitant la comparaison et couvrant plusieurs besoins');
        if (signals.hasOnSiteSearch) structuralStrengths.push(lang === 'ar' ? 'محرك بحث داخلي يسهل اكتشاف المنتجات' : lang === 'en' ? 'On-site search makes product discovery easier' : 'Recherche interne facilitant la decouverte des produits');
        if (signals.hasPaymentOptions) structuralStrengths.push(lang === 'ar' ? 'خيارات دفع واضحة تقلل الاحتكاك عند الشراء' : lang === 'en' ? 'Clear payment options reduce purchase friction' : "Options de paiement claires reduisant la friction d'achat");
        if (signals.brandHasDelivery) structuralStrengths.push(lang === 'ar' ? 'منظومة تسليم ظاهرة تدعم قرار الشراء' : lang === 'en' ? 'Visible delivery system supports purchase decisions' : "Dispositif de livraison visible soutenant la decision d'achat");
        if (signals.brandHasReturns) structuralStrengths.push(lang === 'ar' ? 'سياسة إرجاع أو استرداد تقلل المخاطرة' : lang === 'en' ? 'Returns or refund policy reduces perceived risk' : 'Politique de retour ou remboursement reduisant le risque percu');
        if (signals.hasAccountJourney) structuralStrengths.push(lang === 'ar' ? 'مسار حساب عميل يدعم الشراء المتكرر' : lang === 'en' ? 'Customer account journey supports repeat purchases' : 'Parcours compte client favorisant les achats repetes');
        if (signals.hasLocalPresence) structuralStrengths.push(lang === 'ar' ? 'حضور محلي واضح في السوق المستهدف' : lang === 'en' ? 'Clear local presence in the target market' : 'Presence locale claire sur le marche cible');
        if (signals.hasMobileApp) structuralStrengths.push(lang === 'ar' ? 'تطبيق جوال يوسع الوصول والاحتفاظ' : lang === 'en' ? 'Mobile app extends reach and retention' : 'Application mobile elargissant la portee et la retention');

        const missingProofs = [];
        if (!signals.hasReviews) missingProofs.push(labels.proof);
        if (!signals.hasGuarantee) missingProofs.push(labels.weakTrust);
        if (!signals.hasPrice) missingProofs.push(labels.weakPrice);
        if (!signals.hasDelivery && !signals.hasReturns) missingProofs.push(labels.weakDelivery);
        const deducedWeaknesses = missingProofs.slice(0, 3).map(text =>
            lang === 'ar' ? `فرصة محتملة: ${text}` : lang === 'en' ? `Potential opening: ${text}` : `Ouverture potentielle : ${text}`
        );

        const value = {
            whatTheySell: headings[0] || compactBusinessText(competitor.snippet, 180),
            primaryPromise: headings[1] || '',
            observedStrengths: structuralStrengths.slice(0, 6),
            structuralStrengths: structuralStrengths.slice(0, 6),
            productSignals: productSignals.slice(0, 5),
            siteLevelEvidence: {
                url: originUrl,
                strengths: structuralStrengths.slice(0, 6),
                signals: {
                    marketplace: signals.hasMarketplaceModel,
                    broadCatalog: signals.hasBroadCatalog,
                    onSiteSearch: signals.hasOnSiteSearch,
                    accountJourney: signals.hasAccountJourney,
                    paymentOptions: signals.hasPaymentOptions,
                    delivery: signals.brandHasDelivery,
                    returns: signals.brandHasReturns,
                    mobileApp: signals.hasMobileApp,
                    localPresence: signals.hasLocalPresence
                }
            },
            productLevelEvidence: {
                url: competitor.url,
                signals: productSignals.slice(0, 5)
            },
            deducedWeaknesses,
            missingProofs: missingProofs.slice(0, 4),
            attackAngle: missingProofs[0] || '',
            evidenceLinks,
            confidence: structuralStrengths.length >= 3 ? 'HIGH' : structuralStrengths.length ? 'MEDIUM' : 'LOW',
            observed: true,
            signals
        };
        COMPETITOR_BUSINESS_CACHE.set(cacheKey, { savedAt: Date.now(), value });
        if (COMPETITOR_BUSINESS_CACHE.size > 120) {
            const oldest = COMPETITOR_BUSINESS_CACHE.keys().next().value;
            COMPETITOR_BUSINESS_CACHE.delete(oldest);
        }
        return value;
    } catch (error) {
        console.warn(`[CompetitorBusiness] ${competitor.domain || competitor.url}: ${error.message}`);
        return fallback;
    }
}

async function enrichTopCompetitorsBusiness(competitors = [], lang = 'fr') {
    const targets = competitors.slice(0, 10);
    const results = new Array(targets.length);
    let cursor = 0;
    const worker = async () => {
        while (cursor < targets.length) {
            const index = cursor++;
            results[index] = await fetchCompetitorBusinessProfile(targets[index], lang);
        }
    };
    await Promise.all(Array.from({ length: Math.min(2, targets.length) }, worker));
    return results;
}

function dedupeBusinessActions(actions = []) {
    const seen = [];
    const perCategory = {};
    return actions.filter(item => {
        const normalized = compactBusinessText(item?.action, 300).toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, '');
        if (!normalized || seen.some(x => x.includes(normalized) || normalized.includes(x))) return false;
        const category = item.category || 'positionnement';
        if ((perCategory[category] || 0) >= 2) return false;
        perCategory[category] = (perCategory[category] || 0) + 1;
        seen.push(normalized);
        return true;
    }).slice(0, 10);
}

function hasMeaningfulCompetitorStudyData(value, depth = 0) {
    if (depth > 6 || value === null || value === undefined) return false;
    if (Array.isArray(value)) return value.some(item => hasMeaningfulCompetitorStudyData(item, depth + 1));
    if (typeof value === 'object') {
        const metaKeys = new Set(['status', 'type', 'confidence', 'confidenceExplanation', 'evidenceLinks']);
        return Object.entries(value)
            .filter(([key]) => !metaKeys.has(key))
            .some(([, item]) => hasMeaningfulCompetitorStudyData(item, depth + 1));
    }
    if (typeof value === 'number') return Number.isFinite(value) && value !== 0;
    const text = String(value || '').replace(/\s+/g, ' ').trim();
    if (!text) return false;
    return !/^(?:null|undefined|none|n\/?a|not available|not found|non trouve|non detecte|aucun|aucune|indisponible|error|not_called|غير متوفر|لا يوجد|لا توجد|غير متاح|[-—]+|0)$/i.test(text);
}

// Keep business classification deterministic and local to the competitor pipeline.
// This is a routing signal for copy and actions, not an AI verdict.
function detectCompetitorBusinessArchetype(query = '', competitors = []) {
    const queryText = String(query || '').toLowerCase();
    const records = Array.isArray(competitors) ? competitors : [];
    const corpus = [
        queryText,
        ...records.flatMap(item => [
            item?.title,
            item?.snippet,
            item?.description,
            item?.whatTheySell,
            item?.primaryPromise,
            item?.competitorType,
            item?.category,
            item?.type,
            item?.signals?.offerType,
            item?.signals?.productIntent
        ])
    ].filter(Boolean).join(' ').toLowerCase();

    const servicePattern = /\bagenc(?:e|y)\b|\bservice(?:s)?\b|\bprestation(?:s)?\b|\bconsult(?:ing)?\b|\bconseil\b|\bsaas\b|\bsoftware\b|\blogiciel\b|\bplateforme\b|\bformation\b|\bmarketing\b|\bgrowth\b|\bintelligence artificielle\b|\bb2b\b|\baccompagnement|\baudit\b|\bcoaching\b|\u062e\u062f\u0645\u0629|\u062e\u062f\u0645\u0627\u062a|\u0628\u0631\u0645\u062c\u064a\u0627\u062a|\u0645\u0646\u0635\u0629/i;
    const productPattern = /\be-?commerce\b|\becommerce\b|\bboutique\b|\bshop\b|\bstore\b|\bretail\b|\bmarketplace\b|\bcatalog(?:ue)?\b|\bproduit(?:s)?\b|\bproduct(?:s)?\b|\bappareil\b|\bdevice\b|\bacheter\b|\bbuy\b|\bprix\b|\bprice\b|\blivraison\b|\bdelivery\b|\bstock\b|\bblackhead\b|\bskincare\b|\bcosm[eé]tique\b|\bbeaut[yé]\b|\u0645\u0646\u062a\u062c|\u0645\u062a\u062c\u0631|\u0633\u0639\u0631|\u062a\u0648\u0635\u064a\u0644|\u0645\u0632\u064a\u0644|\u0631\u0624\u0648\u0633\u0627\u0644\u0633\u0648\u062f\u0627\u0621/i;
    const supplementPattern = /\bsupplement(?:s)?\b|\bcompl[eé]ment(?:s)?\b|\bvitamin(?:e|s)?\b|\bcaffeine\b|\bcaf[eé]ine\b|\bginseng\b|\bnutrition\b|\bminer(?:al|aux)\b|\benergy\b|\b[ée]nergie\b|\bfatigue\b|\bconcentration\b|\bsant[eé]\b|\u0645\u0643\u0645\u0644|\u0637\u0627\u0642\u0629|\u062a\u063a\u0630\u064a\u0629/i;

    // The query is the strongest signal: it prevents competitor snippets from
    // changing a service into a product, or a product into a generic service.
    if (servicePattern.test(queryText) && !productPattern.test(queryText)) return 'service';
    if (productPattern.test(queryText)) return 'physical_product';
    if (supplementPattern.test(queryText)) return 'supplement';

    if (servicePattern.test(corpus) && !productPattern.test(corpus)) return 'service';
    if (productPattern.test(corpus) || records.some(item => (
        item?.signals?.hasPrice ||
        item?.signals?.hasProductCards ||
        item?.signals?.hasCatalog
    ))) return 'physical_product';
    if (supplementPattern.test(corpus)) return 'supplement';
    return 'generic';
}

