// ═══════════════════════════════════════════════════════════════════
// STP DECISION ENGINE — Segmentation, Targeting, Positioning
// Uses the existing Daka backend layers first, then applies the
// marketing-framework method as a guardrail against generic output.
// ═══════════════════════════════════════════════════════════════════

function stpText(value, max = 220) {
    return cleanProofText(value, max);
}

function localizeStpSubjectForReport(value = '', lang = 'fr') {
    const raw = stpText(value, 160);
    if (!raw || lang !== 'ar') return raw;
    if (/[\u0600-\u06FF]/.test(raw)) return raw;
    let text = raw.toLowerCase();
    const replacements = [
        [/agence\s+marketing\s+ia|ai\s+marketing\s+agency/g, 'وكالة تسويق بالذكاء الاصطناعي'],
        [/agence\s+marketing/g, 'وكالة تسويق'],
        [/marketing\s+ia|ia\s+marketing|ai\s+marketing/g, 'تسويق بالذكاء الاصطناعي'],
        [/intelligence\s+artificielle|artificial\s+intelligence|\bia\b|\bai\b/g, 'الذكاء الاصطناعي'],
        [/projecteur\s+solaire|solar\s+projector|solar\s+flood\s*light/g, 'كشاف شمسي'],
        [/projecteur/g, 'كشاف'],
        [/solaire|solar/g, 'شمسي'],
        [/lanterne|fanous/g, 'فانوس'],
        [/logiciel\s+de\s+gestion|management\s+software/g, 'برنامج إدارة'],
        [/\bsaas\b/g, 'برنامج ساس'],
        [/e[\s-]?commerce/g, 'تجارة إلكترونية'],
        [/formation|course|training/g, 'تكوين'],
        [/audit/g, 'تدقيق'],
        [/funnel/g, 'مسار البيع'],
        [/seo/g, 'تحسين محركات البحث'],
        [/blackheads?|points?\s+noirs?/g, 'الرؤوس السوداء'],
        [/remover|extracteur/g, 'مزيل']
    ];
    replacements.forEach(([pattern, replacement]) => {
        text = text.replace(pattern, replacement);
    });
    text = text
        .replace(/\b(tunisie|tunisia)\b/g, 'تونس')
        .replace(/\b(maroc|morocco)\b/g, 'المغرب')
        .replace(/\b(libye|libya)\b/g, 'ليبيا')
        .replace(/\b(france)\b/g, 'فرنسا')
        .replace(/\b(usa|united states|états-unis)\b/g, 'الولايات المتحدة')
        .replace(/[,_|/]+/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
    return /[a-z]{3,}/i.test(text) && !/[\u0600-\u06FF]/.test(text) ? raw : text || raw;
}

function stpArray(value, max = 8) {
    const input = Array.isArray(value) ? value : [value];
    return [...new Set(input
        .flatMap(item => Array.isArray(item) ? item : [item])
        .map(item => stpText(item, 220))
        .filter(Boolean))]
        .slice(0, max);
}

function stpEvidence(type, value, source, confidence = 'MEDIUM', evidence = []) {
    const cleanValue = stpText(value, 320);
    if (!cleanValue) return null;
    return {
        type,
        value: cleanValue,
        source: source || 'Daka STP layer',
        confidence,
        evidence: stpArray(evidence, 6)
    };
}

function stpLangPack(lang = 'fr') {
    const code = resolveLang(lang).code;
    return {
        code,
        labels: {
            decision: code === 'ar' ? 'قرار STP' : code === 'en' ? 'STP decision' : 'Décision STP',
            localMarket: code === 'ar' ? 'السوق المحلي' : code === 'en' ? 'local market' : 'marché local',
            proofMissing: code === 'ar' ? 'دليل ناقص' : code === 'en' ? 'missing proof' : 'preuve manquante',
            bestSegment: code === 'ar' ? 'أفضل شريحة' : code === 'en' ? 'best segment' : 'meilleur segment',
            positioning: code === 'ar' ? 'التموضع المقترح' : code === 'en' ? 'recommended positioning' : 'positionnement recommandé'
        }
    };
}

function inferStpArchetype(query = '', competitorData = {}, urlIntel = null) {
    const corpus = [
        query,
        competitorData?.productServiceAudit?.coreOffering,
        competitorData?.grandSlamOfferBlueprint?.theIrresistibleOffer,
        competitorData?.marketInsights?.serpIntent,
        ...(competitorData?.competitors || []).slice(0, 5).map(c => `${c.title || ''} ${c.snippet || ''} ${c.type || ''}`),
        urlIntel?.content?.title,
        urlIntel?.content?.description
    ].filter(Boolean).join(' ').toLowerCase();

    if (/b2b|saas|software|logiciel|crm|platform|plateforme|agency|agence|consult|audit|service|lead|automation|formation|coaching|استشارة|خدمة|وكالة|برنامج|منصة/.test(corpus)) {
        return 'b2b_service';
    }
    if (/prix|acheter|shop|boutique|livraison|cod|cash on delivery|ecommerce|e-commerce|produit|product|سعر|شراء|توصيل|الدفع عند الاستلام|منتج/.test(corpus)) {
        return 'ecommerce_product';
    }
    if (/local|near me|restaurant|clinic|salon|hotel|immobilier|real estate|garage|repair|ville|près|قريب|محلي/.test(corpus)) {
        return 'local_service';
    }
    if (/blog|guide|how to|comment|learn|cours|education|formation|تعلم|شرح|دليل/.test(corpus)) {
        return 'content_education';
    }
    return 'general_market';
}

function buildStpSegmentCandidates({ query = '', geo = '', budget = '', objective = '', competitorData = {}, archetype = 'general_market', lang = 'fr' } = {}) {
    const marketName = localizeCompetitorMarketName(geo, lang);
    const intent = stpText(competitorData?.marketInsights?.serpIntent || competitorData?.marketInsights?.intent || '', 120);
    const leader = competitorData?.top10Competitors?.[0] || competitorData?.competitors?.[0] || {};
    const leaderDomain = stpText(leader.domain || leader.displayed_link || leader.link || leader.url, 120);
    const keywords = stpArray([
        ...(competitorData?.keywordStrategy?.primary || []),
        ...(competitorData?.keywordStrategy?.longTail || []),
        ...(competitorData?.keywords || [])
    ], 8);

    const baseNeed = localizeStpSubjectForReport(query, lang) || stpText(query, 140);
    const candidates = [];

    if (archetype === 'b2b_service') {
        candidates.push(
            {
                id: 'b2b-growth-operators',
                name: lang === 'ar' ? `شركات تبحث عن نمو عملي في ${marketName}` : lang === 'en' ? `${marketName} growth operators` : `Opérateurs de croissance ${marketName}`,
                type: 'demographic+behavioral',
                need: lang === 'ar' ? `تحويل ${baseNeed} إلى نتيجة تجارية قابلة للقياس` : lang === 'en' ? `Turn ${baseNeed} into measurable business impact` : `Transformer ${baseNeed} en impact business mesurable`,
                accessChannels: ['Google Search', 'LinkedIn', 'direct outreach', 'case studies'],
                buyingTriggers: ['budget pressure', 'need for leads', 'weak differentiation', 'competitor pressure']
            },
            {
                id: 'agency-founders',
                name: lang === 'ar' ? 'وكالات ومستشارون يريدون تسليمات أسرع' : lang === 'en' ? 'Agencies and consultants needing faster delivery' : 'Agences et consultants qui veulent livrer plus vite',
                type: 'psychographic+behavioral',
                need: lang === 'ar' ? 'إنتاج تحليل وتسليمات قابلة للبيع بسرعة' : lang === 'en' ? 'Produce sellable analysis and deliverables faster' : 'Produire plus vite des analyses et livrables vendables',
                accessChannels: ['YouTube', 'communities', 'LinkedIn', 'templates'],
                buyingTriggers: ['client deadline', 'need to look strategic', 'report quality gap']
            }
        );
    } else if (archetype === 'ecommerce_product') {
        candidates.push(
            {
                id: 'ready-to-buy-local',
                name: lang === 'ar' ? `مشترون محليون جاهزون في ${marketName}` : lang === 'en' ? `Ready-to-buy local shoppers in ${marketName}` : `Acheteurs locaux prêts à acheter en ${marketName}`,
                type: 'geographic+behavioral',
                need: lang === 'ar' ? `شراء ${baseNeed} بثقة وسرعة` : lang === 'en' ? `Buy ${baseNeed} with trust and speed` : `Acheter ${baseNeed} avec confiance et rapidité`,
                accessChannels: ['Google Shopping/Search', 'Facebook Ads', 'TikTok', 'WhatsApp'],
                buyingTriggers: ['visible result', 'delivery speed', 'COD/payment trust', 'price clarity']
            },
            {
                id: 'comparison-shoppers',
                name: lang === 'ar' ? 'مشترون يقارنون السعر والدليل' : lang === 'en' ? 'Comparison shoppers checking price and proof' : 'Acheteurs qui comparent prix et preuves',
                type: 'behavioral',
                need: lang === 'ar' ? 'فهم الفرق بين العروض قبل الطلب' : lang === 'en' ? 'Understand the difference between offers before ordering' : 'Comprendre la différence entre les offres avant commande',
                accessChannels: ['SERP', 'marketplaces', 'reviews', 'retargeting'],
                buyingTriggers: ['reviews', 'guarantee', 'before/after proof', 'clear return policy']
            }
        );
    } else if (archetype === 'local_service') {
        candidates.push(
            {
                id: 'nearby-high-intent',
                name: lang === 'ar' ? `باحثون محليون بنية عالية في ${marketName}` : lang === 'en' ? `High-intent local searchers in ${marketName}` : `Recherches locales à forte intention en ${marketName}`,
                type: 'geographic+behavioral',
                need: lang === 'ar' ? 'اختيار مزود موثوق قريب بسرعة' : lang === 'en' ? 'Choose a nearby trusted provider quickly' : 'Choisir vite un prestataire proche et fiable',
                accessChannels: ['Google Maps', 'local SEO', 'WhatsApp', 'reviews'],
                buyingTriggers: ['proximity', 'reviews', 'availability', 'proof of work']
            }
        );
    }

    candidates.push({
        id: 'serp-demand-segment',
        name: lang === 'ar' ? `طلب بحث ظاهر حول "${baseNeed}"` : lang === 'en' ? `Visible search demand around "${baseNeed}"` : `Demande de recherche visible autour de "${baseNeed}"`,
        type: 'behavioral+intent',
        need: intent || (lang === 'ar' ? 'حل مشكلة محددة ظهرت في البحث' : lang === 'en' ? 'Solve a specific search-visible problem' : 'Résoudre un besoin visible dans la recherche'),
        accessChannels: ['SEO', 'SERP', 'content', 'landing page'],
        buyingTriggers: keywords.length ? keywords : ['search intent', 'competitor comparison', leaderDomain].filter(Boolean)
    });

    return candidates.slice(0, 5).map((segment, index) => ({
        ...segment,
        rank: index + 1,
        evidence: stpArray([
            leaderDomain ? `SERP leader: ${leaderDomain}` : '',
            intent ? `SERP intent: ${intent}` : '',
            keywords.length ? `Keywords: ${keywords.slice(0, 4).join(', ')}` : '',
            budget ? `Budget input: ${budget}` : '',
            objective ? `Objective input: ${objective}` : ''
        ], 5)
    }));
}

function scoreStpSegments(segments = [], competitorData = {}, inputs = {}) {
    const competitorCount = Number(competitorData?.top10Competitors?.length || competitorData?.competitors?.length || 0);
    const localConfirmed = Number(competitorData?.geoSourceAudit?.localCompetitorsConfirmed || 0);
    const sourceCount = Number(competitorData?.observedUrls?.length || competitorData?.marketSources?.length || 0);
    const keywordCount = Number((competitorData?.keywordStrategy?.primary || []).length + (competitorData?.keywordStrategy?.longTail || []).length);
    const hasBudget = Boolean(stpText(inputs.budget, 60));
    const hasUrl = Boolean(stpText(inputs.url, 120));

    return segments.map(segment => {
        let profitability = 45;
        let scalability = 42;
        let accessibility = 44;
        let proofStrength = 35;

        if (/ready|buy|acheter|مشتر/.test(segment.id + ' ' + segment.name)) profitability += 18;
        if (/b2b|growth|agency|service/.test(segment.id + ' ' + segment.name)) profitability += 14;
        if (competitorCount >= 5) scalability += 16;
        if (keywordCount >= 4) scalability += 12;
        if (localConfirmed > 0) accessibility += 15;
        if (sourceCount >= 5) proofStrength += 18;
        if (hasUrl) proofStrength += 8;
        if (hasBudget) profitability += 5;

        const penalty = competitorData?.dataIntegrity?.riskLevel === 'HIGH' ? 12 : 0;
        const score = Math.round(
            (Math.min(100, profitability) * 0.34) +
            (Math.min(100, scalability) * 0.24) +
            (Math.min(100, accessibility) * 0.24) +
            (Math.min(100, proofStrength) * 0.18)
        ) - penalty;

        return {
            ...segment,
            scores: {
                profitability: clamp(profitability, 0, 100),
                scalability: clamp(scalability, 0, 100),
                accessibility: clamp(accessibility, 0, 100),
                proofStrength: clamp(proofStrength, 0, 100),
                total: clamp(score, 0, 100)
            },
            confidence: proofStrength >= 60 ? 'HIGH' : proofStrength >= 42 ? 'MEDIUM' : 'LOW'
        };
    }).sort((a, b) => b.scores.total - a.scores.total);
}

function inferStpBudgetTier(budget = '') {
    const text = stpText(budget, 120).toLowerCase();
    if (!text) return 'unknown';
    const nums = (text.match(/\d+(?:[.,]\d+)?/g) || []).map(x => Number(String(x).replace(',', '.'))).filter(Number.isFinite);
    const max = nums.length ? Math.max(...nums) : 0;
    if (/free|gratuit|zero|0 dh|0 mad|petit|small|low|faible|محدود|صغير|قليل/.test(text) || (max > 0 && max <= 300)) return 'lean';
    if (/enterprise|large|big|agency|équipe|team|فريق|كبير/.test(text) || max >= 5000) return 'power';
    return 'focused';
}

function normalizeChannelName(value = '') {
    const text = String(value || '').toLowerCase();
    if (/seo|serp|search|google|بحث|محرك|جوجل/.test(text)) return 'seo';
    if (/map|local|maps|خرائط|محلي|قريب/.test(text)) return 'local';
    if (/meta|facebook|instagram|فيسبوك|انستغرام|انستقرام/.test(text)) return 'meta';
    if (/tiktok|تيك/.test(text)) return 'tiktok';
    if (/whatsapp|wa|واتساب|واتس/.test(text)) return 'whatsapp';
    if (/linkedin|b2b|outreach|لينكد|شركات/.test(text)) return 'b2b';
    if (/marketplace|shopping|سوق|متجر|تسوق/.test(text)) return 'marketplace';
    return text.replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 32);
}

function classifyStpAttackChannel(channel = '', lang = 'fr') {
    const raw = stpText(channel, 80);
    const norm = normalizeChannelName(raw);
    const isAr = lang === 'ar';
    const isEn = lang === 'en';
    const label = (fr, en, ar) => isAr ? ar : isEn ? en : fr;
    if (/seo|serp|content|blog|landing/.test(norm)) {
        return { name: raw || 'SEO', type: 'Inbound', role: label('Capturer la demande existante', 'Capture existing demand', 'التقاط الطلب الموجود'), timing: 'now' };
    }
    if (/linkedin|outreach|b2b|direct/.test(norm)) {
        return { name: raw || 'Direct outreach', type: 'Outbound', role: label('Créer des conversations ciblées', 'Create targeted conversations', 'خلق محادثات مستهدفة'), timing: 'now' };
    }
    if (/meta|tiktok|shopping|ads|marketplace/.test(norm)) {
        return { name: raw || 'Paid acquisition', type: 'Paid', role: label('Tester rapidement les angles et offres', 'Test angles and offers quickly', 'اختبار الزوايا والعروض بسرعة'), timing: 'after-proof' };
    }
    if (/whatsapp|email|newsletter|community/.test(norm)) {
        return { name: raw || 'Owned channel', type: 'Owned', role: label('Convertir et relancer sans dépendre uniquement des ads', 'Convert and follow up without relying only on ads', 'التحويل والمتابعة دون الاعتماد فقط على الإعلانات'), timing: 'now' };
    }
    if (/local|maps|review/.test(norm)) {
        return { name: raw || 'Local SEO', type: 'Local', role: label('Gagner la demande géographique proche', 'Win nearby geographic demand', 'كسب الطلب الجغرافي القريب'), timing: 'now' };
    }
    if (/partner|affiliate|reseller|influence/.test(norm)) {
        return { name: raw || 'Partnership', type: 'Partnership', role: label('Accéder à une audience déjà agrégée', 'Access an already aggregated audience', 'الوصول إلى جمهور مجمع مسبقا'), timing: 'after-proof' };
    }
    return { name: raw || 'Market test', type: 'Experiment', role: label('Tester une poche de marché sans surinvestir', 'Test a market pocket without overinvesting', 'اختبار جيب سوقي دون استثمار زائد'), timing: 'test' };
}

function stpFirstUseful(values = [], max = 220) {
    return stpArray(values, 12).map(value => stpText(value, max)).find(Boolean) || '';
}

function stpCompetitorCandidates(competitorData = {}) {
    const buckets = [
        competitorData?.top10Competitors,
        competitorData?.competitors,
        competitorData?.directCompetitors,
        competitorData?.competitorIntelligence?.competitorProfiles,
        competitorData?.competitorIntelligence?.surveillance?.competitors,
        competitorData?.marketSources
    ].filter(Array.isArray);
    const seen = new Set();
    return buckets.flat().map(item => {
        const title = stpText(item?.title || item?.name || item?.domain || item?.displayed_link, 140);
        const url = stpText(item?.url || item?.link || item?.website, 240);
        const domain = stpText(item?.domain || item?.displayed_link || (() => {
            try { return url ? new URL(url).hostname.replace(/^www\./, '') : ''; } catch (_) { return ''; }
        })(), 140);
        const key = (domain || title || url).toLowerCase();
        if (!key || seen.has(key)) return null;
        seen.add(key);
        return {
            title,
            domain,
            url,
            snippet: stpText(item?.snippet || item?.description || item?.summary, 260),
            type: stpText(item?.type || item?.classification || item?.category, 80)
        };
    }).filter(Boolean).slice(0, 10);
}

function inferStpBusinessModelLabel(archetype = 'general_market', corpus = '', lang = 'fr') {
    const text = String(corpus || '').toLowerCase();
    const isAr = lang === 'ar';
    const isEn = lang === 'en';
    if (/saas|software|logiciel|subscription|abonnement|برنامج|منصة|اشتراك/.test(text)) {
        return isAr ? 'نموذج SaaS / اشتراك' : isEn ? 'SaaS / subscription' : 'SaaS / abonnement';
    }
    if (/agency|agence|consult|audit|service|lead|b2b|وكالة|استشارة|خدمة/.test(text) || archetype === 'b2b_service') {
        return isAr ? 'خدمة B2B / وكالة / استشارة' : isEn ? 'B2B service / agency / consulting' : 'Service B2B / agence / conseil';
    }
    if (/cod|cash on delivery|livraison|shop|boutique|ecommerce|e-commerce|منتج|شراء|توصيل|الدفع عند الاستلام/.test(text) || archetype === 'ecommerce_product') {
        return isAr ? 'تجارة إلكترونية / بيع مباشر' : isEn ? 'E-commerce / direct response' : 'E-commerce / vente directe';
    }
    if (/maps|near me|local|clinic|restaurant|salon|garage|محلي|قريب/.test(text) || archetype === 'local_service') {
        return isAr ? 'خدمة محلية عالية النية' : isEn ? 'High-intent local service' : 'Service local à forte intention';
    }
    if (/blog|guide|learn|cours|formation|تعلم|دليل|شرح/.test(text) || archetype === 'content_education') {
        return isAr ? 'تعليم / محتوى / توليد طلب' : isEn ? 'Education / content demand generation' : 'Éducation / contenu / génération de demande';
    }
    return isAr ? 'نموذج سوق عام يحتاج اختبارا' : isEn ? 'General market model to validate' : 'Modèle marché général à valider';
}

function inferStpAudienceLabel(archetype = 'general_market', query = '', market = '', lang = 'fr') {
    const isAr = lang === 'ar';
    const isEn = lang === 'en';
    const need = stpText(query, 90);
    if (archetype === 'b2b_service') {
        return isAr ? `شركات وفرق نمو تبحث عن ${need} في ${market}` : isEn ? `Companies and growth teams looking for ${need} in ${market}` : `Entreprises et équipes growth cherchant ${need} en ${market}`;
    }
    if (archetype === 'ecommerce_product') {
        return isAr ? `مشترون جاهزون يقارنون ${need} في ${market}` : isEn ? `Ready-to-buy shoppers comparing ${need} in ${market}` : `Acheteurs prêts à commander qui comparent ${need} en ${market}`;
    }
    if (archetype === 'local_service') {
        return isAr ? `باحثون محليون بنية عالية حول ${need} في ${market}` : isEn ? `High-intent local searchers around ${need} in ${market}` : `Recherches locales à forte intention autour de ${need} en ${market}`;
    }
    if (archetype === 'content_education') {
        return isAr ? `جمهور يبحث عن فهم وحل مشكلة ${need}` : isEn ? `Audience trying to understand and solve ${need}` : `Audience qui cherche à comprendre et résoudre ${need}`;
    }
    return isAr ? `جمهور طلب ظاهر حول ${need} في ${market}` : isEn ? `Visible-demand audience around ${need} in ${market}` : `Audience de demande visible autour de ${need} en ${market}`;
}

function inferStpChannels({ archetype = 'general_market', competitorData = {}, query = '', lang = 'fr' } = {}) {
    const competitorCorpus = stpCompetitorCandidates(competitorData)
        .map(item => `${item.title} ${item.snippet} ${item.type} ${item.domain}`)
        .join(' ')
        .toLowerCase();
    const corpus = `${query} ${competitorCorpus}`.toLowerCase();
    const channels = [];
    const add = (...items) => items.forEach(item => { if (item && !channels.includes(item)) channels.push(item); });

    if (archetype === 'b2b_service') add('Google Search', 'LinkedIn', 'direct outreach', 'case studies');
    if (archetype === 'ecommerce_product') add('Google Search/Shopping', 'Meta Ads', 'TikTok', 'WhatsApp');
    if (archetype === 'local_service') add('Google Maps', 'local SEO', 'WhatsApp', 'reviews');
    if (archetype === 'content_education') add('SEO', 'YouTube', 'communities', 'newsletter');
    if (/instagram|facebook|meta/.test(corpus)) add('Meta Ads');
    if (/tiktok|تيك/.test(corpus)) add('TikTok');
    if (/maps|local|near|ville|محلي|قريب/.test(corpus) || competitorData?.geoSourceAudit?.localCompetitorsConfirmed) add('Google Maps', 'local SEO');
    if (/marketplace|shop|shopping|amazon|noon|jumia|boutique|متجر|سوق/.test(corpus)) add('marketplaces', 'Google Shopping');
    if (/whatsapp|واتساب|wa/.test(corpus)) add('WhatsApp');
    if (!channels.length) add('SEO', 'landing page', 'competitor comparison');
    return stpArray(channels, 8);
}

function inferStpConstraints({ competitorData = {}, archetype = '', budget = '', url = '', lang = 'fr' } = {}) {
    const isAr = lang === 'ar';
    const isEn = lang === 'en';
    const constraints = [];
    const competitorCount = Number(competitorData?.top10Competitors?.length || competitorData?.competitors?.length || 0);
    const localConfirmed = Number(competitorData?.geoSourceAudit?.localCompetitorsConfirmed || 0);
    const sourceCount = Number(competitorData?.observedUrls?.length || competitorData?.marketSources?.length || 0);
    const budgetTier = inferStpBudgetTier(budget);

    if (competitorData?.dataIntegrity?.riskLevel === 'HIGH') {
        constraints.push(isAr ? 'الثقة في البيانات تحتاج تحقق إضافي قبل التوسع' : isEn ? 'data confidence needs extra verification before scaling' : 'confiance data à vérifier avant scale');
    }
    if (!url) {
        constraints.push(isAr ? 'لا يوجد موقع مرجعي للمقارنة المباشرة' : isEn ? 'no benchmark URL provided for direct comparison' : 'aucune URL benchmark fournie pour comparaison directe');
    }
    if (competitorCount >= 8) {
        constraints.push(isAr ? 'ضغط منافسين مرتفع على SERP' : isEn ? 'high competitor pressure on SERP' : 'pression concurrentielle élevée sur la SERP');
    }
    if (localConfirmed === 0) {
        constraints.push(isAr ? 'الفائز المحلي يحتاج تأكيدا ميدانيا' : isEn ? 'local winner still needs field validation' : 'leader local à confirmer terrain');
    }
    if (sourceCount < 4) {
        constraints.push(isAr ? 'عدد مصادر السوق محدود' : isEn ? 'limited market source depth' : 'profondeur de sources marché limitée');
    }
    if (budgetTier === 'lean') {
        constraints.push(isAr ? 'الميزانية تفرض اختبارا ضيقا لا حملة واسعة' : isEn ? 'budget requires a narrow test, not a broad campaign' : 'budget impose un test étroit, pas une campagne large');
    }
    if (archetype === 'ecommerce_product') {
        constraints.push(isAr ? 'يجب إثبات السعر والتوصيل والضمان قبل الوعد الكبير' : isEn ? 'price, delivery and guarantee must be proven before the big promise' : 'prix, livraison et garantie à prouver avant grande promesse');
    }
    return stpArray(constraints, 8);
}

function inferStpOperatingContext({ query = '', geo = '', lang = 'fr', url = '', budget = '', objective = '', businessModel = '', context = {}, competitorData = {}, userSiteData = null, archetype = 'general_market' } = {}) {
    const market = localizeCompetitorMarketName(geo || competitorData?.geo || context?.selectedCountry, lang);
    const competitors = stpCompetitorCandidates(competitorData);
    const corpus = [
        query,
        competitorData?.productServiceAudit?.coreOffering,
        competitorData?.grandSlamOfferBlueprint?.theIrresistibleOffer,
        competitorData?.marketInsights?.serpIntent,
        userSiteData?.content?.title,
        userSiteData?.content?.description,
        competitors.map(c => `${c.title} ${c.snippet} ${c.type}`).join(' ')
    ].filter(Boolean).join(' ');

    const inferredValues = {
        offer: stpFirstUseful([
            context?.offer,
            competitorData?.productServiceAudit?.coreOffering,
            competitorData?.grandSlamOfferBlueprint?.theIrresistibleOffer,
            query
        ], 180),
        audience: stpFirstUseful([
            context?.audience,
            context?.userAudience,
            inferStpAudienceLabel(archetype, query, market, lang)
        ], 180),
        objective: stpFirstUseful([
            context?.objective,
            objective,
            competitorData?.winningMove,
            lang === 'ar' ? 'اختيار شريحة أولى قابلة للكسب بسرعة' : lang === 'en' ? 'choose the first segment that can be won quickly' : 'choisir la première poche de marché gagnable rapidement'
        ], 180),
        businessModel: stpFirstUseful([
            context?.businessModel,
            businessModel,
            inferStpBusinessModelLabel(archetype, corpus, lang)
        ], 140),
        cityOrRegion: stpFirstUseful([
            context?.cityOrRegion,
            competitorData?.geoSourceAudit?.target,
            geo,
            market
        ], 110),
        knownCompetitors: stpArray(context?.knownCompetitors?.length ? context.knownCompetitors : competitors.map(c => c.domain || c.title || c.url), 10),
        constraints: stpArray(context?.constraints?.length ? context.constraints : inferStpConstraints({ competitorData, archetype, budget, url, lang }), 8),
        channels: stpArray(context?.channels?.length ? context.channels : inferStpChannels({ archetype, competitorData, query, lang }), 8)
    };

    const userProvided = {
        offer: Boolean(stpText(context?.offer, 30)),
        audience: Boolean(stpText(context?.audience || context?.userAudience, 30)),
        objective: Boolean(stpText(context?.objective || objective, 30)),
        businessModel: Boolean(stpText(context?.businessModel || businessModel, 30)),
        cityOrRegion: Boolean(stpText(context?.cityOrRegion, 30)),
        knownCompetitors: Boolean(stpArray(context?.knownCompetitors, 1).length),
        constraints: Boolean(stpArray(context?.constraints, 1).length),
        channels: Boolean(stpArray(context?.channels, 1).length)
    };

    const field = (key, value, source, confidence = 'MEDIUM', evidence = []) => ({
        key,
        value,
        source: userProvided[key] ? 'user_override' : source,
        confidence: userProvided[key] ? 'HIGH' : confidence,
        evidence: stpArray(evidence, 5),
        inferred: !userProvided[key]
    });

    const fields = {
        offer: field('offer', inferredValues.offer, 'Product/service + SERP intent layer', inferredValues.offer === query ? 'LOW' : 'MEDIUM', [competitorData?.productServiceAudit?.coreOffering, competitorData?.grandSlamOfferBlueprint?.theIrresistibleOffer, query]),
        audience: field('audience', inferredValues.audience, 'Audience archetype layer', 'MEDIUM', [archetype, competitorData?.marketInsights?.serpIntent]),
        objective: field('objective', inferredValues.objective, 'Winning move + STP objective layer', 'MEDIUM', [competitorData?.winningMove, objective]),
        businessModel: field('businessModel', inferredValues.businessModel, 'Business archetype detector', 'MEDIUM', [archetype]),
        cityOrRegion: field('cityOrRegion', inferredValues.cityOrRegion, 'Geo resolution layer', 'HIGH', [geo, competitorData?.geoSourceAudit?.target]),
        knownCompetitors: field('knownCompetitors', inferredValues.knownCompetitors, 'Competitor SERP layer', competitors.length ? 'HIGH' : 'LOW', competitors.slice(0, 5).map(c => c.url || c.domain)),
        constraints: field('constraints', inferredValues.constraints, 'Risk and feasibility layer', 'MEDIUM', [competitorData?.dataIntegrity?.riskLevel, inferStpBudgetTier(budget)]),
        channels: field('channels', inferredValues.channels, 'Channel access layer', 'MEDIUM', [archetype, competitorData?.geoSourceAudit?.localCompetitorsConfirmed])
    };

    return {
        mode: Object.values(userProvided).some(Boolean) ? 'user_enriched' : 'fully_deduced',
        values: inferredValues,
        fields,
        evidence: Object.values(fields)
            .filter(item => item.value && item.inferred)
            .map(item => stpEvidence('inferred', Array.isArray(item.value) ? item.value.join(', ') : item.value, item.source, item.confidence, item.evidence))
            .filter(Boolean)
    };
}

function buildBeachheadMarketDecision({ segments = [], competitorData = {}, inputs = {}, archetype = 'general_market', lang = 'fr' } = {}) {
    const isAr = lang === 'ar';
    const isEn = lang === 'en';
    const market = localizeCompetitorMarketName(inputs.geo || competitorData?.geo, lang);
    const budgetTier = inferStpBudgetTier(inputs.budget);
    const contextChannels = stpArray(inputs.context?.channels || [], 8).map(normalizeChannelName).filter(Boolean);
    const constraints = stpArray(inputs.context?.constraints || [], 6);
    const competitorCount = Number(competitorData?.top10Competitors?.length || competitorData?.competitors?.length || 0);
    const localConfirmed = Number(competitorData?.geoSourceAudit?.localCompetitorsConfirmed || 0);
    const sourceCount = Number(competitorData?.observedUrls?.length || competitorData?.marketSources?.length || 0);
    const keywordCount = Number((competitorData?.keywordStrategy?.primary || []).length + (competitorData?.keywordStrategy?.longTail || []).length);

    const evaluated = (segments || []).map((segment) => {
        const segmentChannels = stpArray(segment.accessChannels || [], 8).map(normalizeChannelName).filter(Boolean);
        const channelOverlap = contextChannels.length
            ? segmentChannels.filter(ch => contextChannels.includes(ch)).length
            : Math.min(2, segmentChannels.length);

        let urgency = /ready|buy|acheter|مشتر|intent|demand|طلب/i.test(`${segment.id} ${segment.name}`) ? 78 : 58;
        let access = 46 + (channelOverlap * 13) + (localConfirmed > 0 ? 8 : 0);
        let budgetFit = budgetTier === 'lean' ? 54 : budgetTier === 'power' ? 72 : 64;
        let proof = 38 + Math.min(24, sourceCount * 3) + Math.min(14, keywordCount * 2);
        let competitiveSpace = competitorCount <= 3 ? 76 : competitorCount <= 8 ? 62 : 48;
        let expansion = /b2b|agency|growth|service|serp|search|demand/i.test(`${segment.id} ${segment.name}`) ? 72 : 58;

        if (budgetTier === 'lean' && /seo|serp|content|whatsapp/.test(segmentChannels.join(' '))) budgetFit += 12;
        if (budgetTier === 'lean' && /marketplace|ads/.test(segmentChannels.join(' '))) budgetFit -= 7;
        if (constraints.length) proof += 4;
        if (competitorData?.dataIntegrity?.riskLevel === 'HIGH') proof -= 12;

        const fitScore = Math.round(
            clamp(urgency, 0, 100) * 0.22 +
            clamp(access, 0, 100) * 0.22 +
            clamp(budgetFit, 0, 100) * 0.20 +
            clamp(proof, 0, 100) * 0.16 +
            clamp(competitiveSpace, 0, 100) * 0.12 +
            clamp(expansion, 0, 100) * 0.08
        );

        return {
            segment,
            fitScore: clamp(fitScore, 0, 100),
            dimensions: {
                urgency: clamp(Math.round(urgency), 0, 100),
                accessibility: clamp(Math.round(access), 0, 100),
                budgetFit: clamp(Math.round(budgetFit), 0, 100),
                proofStrength: clamp(Math.round(proof), 0, 100),
                competitiveSpace: clamp(Math.round(competitiveSpace), 0, 100),
                expansionPotential: clamp(Math.round(expansion), 0, 100)
            },
            channelOverlap,
            confidence: proof >= 64 && access >= 62 ? 'HIGH' : proof >= 46 ? 'MEDIUM' : 'LOW'
        };
    }).sort((a, b) => b.fitScore - a.fitScore);

    const winner = evaluated[0] || { segment: segments[0] || {}, fitScore: 0, dimensions: {}, confidence: 'LOW' };
    const next = evaluated[1]?.segment;
    const winningSegment = winner.segment || {};
    const accessChannels = stpArray(winningSegment.accessChannels || [], 4);
    const firstAccess = accessChannels[0] || (isAr ? 'البحث العضوي' : isEn ? 'organic search' : 'recherche organique');
    const budgetLabel = budgetTier === 'lean'
        ? (isAr ? 'مناسب لاختبار محدود الميزانية' : isEn ? 'fit for a lean budget test' : 'adapté à un test budget maîtrisé')
        : budgetTier === 'power'
            ? (isAr ? 'يمكن دعمه بميزانية توسع' : isEn ? 'can support a scale budget' : 'peut supporter un budget de scale')
            : (isAr ? 'مناسب لاختبار مركز' : isEn ? 'fit for a focused test' : 'adapté à un test focalisé');

    return {
        segmentId: winningSegment.id || '',
        name: winningSegment.name || (isAr ? `سوق انطلاق في ${market}` : isEn ? `Beachhead in ${market}` : `Beachhead en ${market}`),
        focus: winningSegment.need || '',
        rationale: isAr
            ? `ابدأ بهذه الشريحة لأنها تضيق السوق إلى طلب قابل للوصول في ${market}، وتربط الميزانية بالقناة الأولى بدل مهاجمة السوق كاملا.`
            : isEn
                ? `Start here because it narrows the market to a reachable demand pocket in ${market}, tying resources to the first accessible channel instead of attacking the whole market.`
                : `Commencer ici réduit le marché à une poche de demande atteignable en ${market}, avec une première voie d’accès réaliste au lieu d’attaquer tout le marché.`,
        fitScore: winner.fitScore,
        confidence: winner.confidence,
        budgetTier,
        budgetFit: budgetLabel,
        accessPath: isAr
            ? `القناة الأولى: ${firstAccess}`
            : isEn
                ? `First access path: ${firstAccess}`
                : `Premier accès: ${firstAccess}`,
        expansionPath: next?.name
            ? (isAr ? `بعد الإثبات: ${next.name}` : isEn ? `After proof: ${next.name}` : `Après preuve: ${next.name}`)
            : '',
        criteria: stpArray([
            isAr ? `إلحاح: ${winner.dimensions.urgency || 0}/100` : isEn ? `Urgency: ${winner.dimensions.urgency || 0}/100` : `Urgence: ${winner.dimensions.urgency || 0}/100`,
            isAr ? `سهولة الوصول: ${winner.dimensions.accessibility || 0}/100` : isEn ? `Accessibility: ${winner.dimensions.accessibility || 0}/100` : `Accessibilité: ${winner.dimensions.accessibility || 0}/100`,
            isAr ? `ملاءمة الميزانية: ${winner.dimensions.budgetFit || 0}/100` : isEn ? `Budget fit: ${winner.dimensions.budgetFit || 0}/100` : `Fit budget: ${winner.dimensions.budgetFit || 0}/100`,
            isAr ? `قوة الدليل: ${winner.dimensions.proofStrength || 0}/100` : isEn ? `Proof strength: ${winner.dimensions.proofStrength || 0}/100` : `Force de preuve: ${winner.dimensions.proofStrength || 0}/100`
        ], 6),
        risks: stpArray([
            competitorData?.dataIntegrity?.riskLevel === 'HIGH'
                ? (isAr ? 'الثقة في البيانات تحتاج تحقق إضافي' : isEn ? 'data confidence needs extra verification' : 'confiance data à vérifier')
                : '',
            constraints.length ? constraints.join(', ') : ''
        ], 4),
        evaluatedSegments: evaluated.map(item => ({
            id: item.segment.id,
            name: item.segment.name,
            fitScore: item.fitScore,
            dimensions: item.dimensions,
            confidence: item.confidence
        }))
    };
}

function buildStpDecisionCards({ chosenSegment = {}, beachheadMarket = {}, persona = {}, positioning = {}, actions = [], competitorData = {}, lang = 'fr' } = {}) {
    const isAr = lang === 'ar';
    const isEn = lang === 'en';
    const label = {
        segment: isAr ? 'الشريحة الفائزة' : isEn ? 'Winning segment' : 'Segment gagnant',
        beachhead: isAr ? 'سوق الانطلاق' : isEn ? 'Beachhead market' : 'Beachhead market',
        positioning: isAr ? 'التموضع' : isEn ? 'Positioning' : 'Positionnement',
        persona: isAr ? 'الشخصية' : isEn ? 'Persona' : 'Persona',
        actions: isAr ? 'أولويات التنفيذ' : isEn ? 'Execution priorities' : 'Priorités d’exécution',
        proof: isAr ? 'الدليل والثقة' : isEn ? 'Proof and confidence' : 'Preuves et confiance',
        competitors: isAr ? 'ضغط المنافسة' : isEn ? 'Competitive pressure' : 'Pression concurrentielle'
    };

    const pushIfUseful = (cards, card) => {
        const hasMain = stpText(card.title || card.body, 260);
        const hasItems = stpArray(card.items || [], 8).length;
        if (!hasMain && !hasItems) return;
        cards.push({
            kind: card.kind,
            tone: card.tone,
            icon: card.icon,
            label: card.label,
            title: stpText(card.title, 260),
            body: stpText(card.body, 420),
            items: stpArray(card.items || [], 8),
            chips: stpArray(card.chips || [], 5)
        });
    };

    const cards = [];
    pushIfUseful(cards, {
        kind: 'segment',
        tone: '34,211,238',
        icon: 'fa-bullseye',
        label: label.segment,
        title: chosenSegment?.name,
        body: chosenSegment?.need,
        items: chosenSegment?.buyingTriggers || chosenSegment?.evidence,
        chips: [chosenSegment?.confidence, chosenSegment?.type]
    });
    pushIfUseful(cards, {
        kind: 'beachhead',
        tone: '34,197,94',
        icon: 'fa-flag-checkered',
        label: label.beachhead,
        title: beachheadMarket?.name,
        body: beachheadMarket?.rationale || beachheadMarket?.focus,
        items: [beachheadMarket?.budgetFit, beachheadMarket?.accessPath, beachheadMarket?.expansionPath, ...(beachheadMarket?.criteria || [])],
        chips: [beachheadMarket?.confidence, beachheadMarket?.fitScore ? `${beachheadMarket.fitScore}/100` : '']
    });
    pushIfUseful(cards, {
        kind: 'positioning',
        tone: '139,92,246',
        icon: 'fa-chess-knight',
        label: label.positioning,
        title: positioning?.audience,
        body: positioning?.statement,
        items: positioning?.differentiatedBenefits,
        chips: [positioning?.proofStatus]
    });
    pushIfUseful(cards, {
        kind: 'persona',
        tone: '245,158,11',
        icon: 'fa-user-check',
        label: label.persona,
        title: persona?.name,
        body: persona?.jobToBeDone,
        items: [...(persona?.pains || []), ...(persona?.objections || [])],
        chips: persona?.alternatives
    });
    pushIfUseful(cards, {
        kind: 'actions',
        tone: '236,72,153',
        icon: 'fa-bolt',
        label: label.actions,
        title: isAr ? 'ما يجب مهاجمته أولا' : isEn ? 'What to attack first' : 'Ce qu’il faut attaquer en premier',
        items: actions.map(item => item?.action || item),
        chips: actions.slice(0, 3).flatMap(item => [item?.impact, item?.effort])
    });
    pushIfUseful(cards, {
        kind: 'proof',
        tone: '59,130,246',
        icon: 'fa-shield-halved',
        label: label.proof,
        title: positioning?.proofStatus,
        body: isAr ? 'لا توسع الوعد قبل تثبيت الدليل المطلوب.' : isEn ? 'Do not expand the promise before proof is secured.' : 'Ne pas élargir la promesse avant de sécuriser la preuve.',
        items: positioning?.proof || persona?.proofNeeded,
        chips: [competitorData?.dataIntegrity?.riskLevel]
    });
    pushIfUseful(cards, {
        kind: 'competitors',
        tone: '248,113,113',
        icon: 'fa-ranking-star',
        label: label.competitors,
        title: isAr ? `${competitorData?.top10Competitors?.length || competitorData?.competitors?.length || 0} منافسين مرصودين` : isEn ? `${competitorData?.top10Competitors?.length || competitorData?.competitors?.length || 0} competitors observed` : `${competitorData?.top10Competitors?.length || competitorData?.competitors?.length || 0} concurrents observés`,
        items: (competitorData?.top10Competitors || competitorData?.competitors || []).slice(0, 4).map(c => c.domain || c.title || c.url || c.link),
        chips: [competitorData?.geoSourceAudit?.target]
    });

    return cards.slice(0, 8);
}

function buildStpPersona(segment = {}, inputs = {}, competitorData = {}, lang = 'fr') {
    const isAr = lang === 'ar';
    const isEn = lang === 'en';
    const market = localizeCompetitorMarketName(inputs.geo || competitorData?.geo, lang);
    const query = localizeStpSubjectForReport(inputs.query || competitorData?.query, lang) || stpText(inputs.query || competitorData?.query, 120);
    const audience = stpText(inputs.context?.audience || inputs.context?.userAudience, 160);
    const leader = competitorData?.top10Competitors?.[0] || competitorData?.competitors?.[0] || {};
    const segmentText = `${segment.id || ''} ${segment.name || ''} ${segment.need || ''} ${stpArray(segment.buyingTriggers, 4).join(' ')}`.toLowerCase();
    const personaJtbd = (() => {
        if (/compar|price|prix|سعر|مقارن|budget|ميزانية/.test(segmentText)) {
            return isAr
                ? `عندما أقارن ${query} في ${market}، أريد معرفة الفرق في السعر والشروط والدليل قبل أن أشتري.`
                : isEn
                    ? `When I compare ${query} in ${market}, I want price, terms and proof to be clear before I buy.`
                    : `Quand je compare ${query} en ${market}, je veux comprendre le prix, les conditions et les preuves avant d’acheter.`;
        }
        if (/proof|trust|review|avis|guarantee|دليل|ثقة|ضمان|مراجعات/.test(segmentText)) {
            return isAr
                ? `عندما أرى ${query} في ${market}، أريد دليلا واضحا وضمانا يزيل الخوف من الاختيار الخاطئ.`
                : isEn
                    ? `When I discover ${query} in ${market}, I want proof and a guarantee that reduce the fear of choosing wrong.`
                    : `Quand je découvre ${query} en ${market}, je veux des preuves et une garantie qui réduisent le risque de mauvais choix.`;
        }
        if (/urgent|ready|buy|achat|شراء|جاهز|عاجل/.test(segmentText)) {
            return isAr
                ? `عندما أبحث عن ${query} في ${market}، أريد عرضا مباشرا يوضح ماذا أفعل الآن وكيف أطلب بسرعة.`
                : isEn
                    ? `When I search for ${query} in ${market}, I want a direct offer that shows what to do now and how to order quickly.`
                    : `Quand je cherche ${query} en ${market}, je veux une offre directe qui montre quoi faire maintenant et comment commander vite.`;
        }
        if (/expert|b2b|agency|service|خبير|وكالة|خدمة/.test(segmentText)) {
            return isAr
                ? `عندما أقيّم ${query} في ${market}، أريد رؤية خبرة ومنهج واضح قبل أن أثق بالجهة المقدمة.`
                : isEn
                    ? `When I evaluate ${query} in ${market}, I want expertise and a clear method before trusting the provider.`
                    : `Quand j’évalue ${query} en ${market}, je veux voir l’expertise et la méthode avant de faire confiance.`;
        }
        return isAr
            ? `عندما أحتاج ${query} في ${market}، أريد اختيار زاوية واضحة تناسب حالتي بدل عرض عام يشبه المنافسين.`
            : isEn
                ? `When I need ${query} in ${market}, I want a clear angle that fits my situation instead of a generic competitor-like offer.`
                : `Quand j’ai besoin de ${query} en ${market}, je veux un angle clair adapté à ma situation, pas une offre générique comme les concurrents.`;
    })();
    const alternatives = stpArray([
        ...(inputs.context?.knownCompetitors || []),
        leader.domain || leader.displayed_link || leader.link,
        ...(competitorData?.foreignBenchmarkLinks || []).slice(0, 2).map(x => x.domain || x.url),
        isAr ? 'عدم الشراء أو انتظار توصية' : isEn ? 'doing nothing or waiting for a referral' : 'ne rien faire ou attendre une recommandation'
    ], 5);

    return {
        name: audience || (isAr ? 'الشخصية ذات الأولوية' : isEn ? 'Priority persona' : 'Persona prioritaire'),
        segmentId: segment.id,
        market,
        jobToBeDone: personaJtbd,
        pains: stpArray([
            competitorData?.productServiceAudit?.weakestProductFeature,
            competitorData?.marketInsights?.painPoint,
            isAr ? 'عدم وضوح السعر أو الدليل أو الضمان' : isEn ? 'unclear price, proof, or guarantee' : 'prix, preuve ou garantie peu clairs'
        ], 4),
        motivations: stpArray([
            segment.need,
            competitorData?.grandSlamOfferBlueprint?.theIrresistibleOffer,
            isAr ? 'نتيجة واضحة بأقل مجهود' : isEn ? 'clear result with less effort' : 'résultat clair avec moins d’effort'
        ], 4),
        objections: stpArray([
            isAr ? 'هل هذا مناسب لي؟' : isEn ? 'Is this right for me?' : 'Est-ce adapté à moi ?',
            isAr ? 'هل يوجد دليل كاف؟' : isEn ? 'Is there enough proof?' : 'Y a-t-il assez de preuves ?',
            isAr ? 'ما الفرق عن البدائل؟' : isEn ? 'What is different from alternatives?' : 'Quelle différence avec les alternatives ?'
        ], 4),
        alternatives,
        proofNeeded: stpArray([
            isAr ? 'دليل نتيجة أو حالة استخدام' : isEn ? 'result proof or use case' : 'preuve de résultat ou cas d’usage',
            isAr ? 'سعر وشروط واضحة' : isEn ? 'clear price and terms' : 'prix et conditions clairs',
            isAr ? 'ضمان أو سياسة رجوع قابلة للتحقق' : isEn ? 'verifiable guarantee or return policy' : 'garantie ou politique de retour vérifiable'
        ], 4)
    };
}

function buildStpPersonaCards({ segments = [], inputs = {}, competitorData = {}, beachheadMarket = {}, archetype = 'general_market', lang = 'fr' } = {}) {
    const isAr = lang === 'ar';
    const isEn = lang === 'en';
    const market = localizeCompetitorMarketName(inputs.geo || competitorData?.geo, lang);
    const query = localizeStpSubjectForReport(inputs.query || competitorData?.query, lang) || stpText(inputs.query || competitorData?.query, 120);
    const ctx = inputs.context || {};
    const channels = stpArray(ctx.channels, 6);
    const constraints = stpArray(ctx.constraints, 5);
    const knownCompetitors = stpArray(ctx.knownCompetitors, 5);
    const offer = localizeStpSubjectForReport(ctx.offer || query, lang) || stpText(ctx.offer || query, 160);
    const defaultProof = stpArray([
        isAr ? 'إثبات النتيجة قبل الوعد' : isEn ? 'proof of result before the promise' : 'preuve du résultat avant la promesse',
        isAr ? 'سعر وشروط واضحة' : isEn ? 'clear price and terms' : 'prix et conditions clairs',
        isAr ? 'مقارنة واضحة مع البدائل' : isEn ? 'clear comparison against alternatives' : 'comparaison claire contre les alternatives'
    ], 4);

    const labels = {
        highIntent: isAr ? 'صاحب نية شراء عالية' : isEn ? 'High-intent buyer' : 'Acheteur à forte intention',
        comparator: isAr ? 'المقارن قبل القرار' : isEn ? 'Comparison shopper' : 'Comparateur avant décision',
        trust: isAr ? 'طالب الثقة' : isEn ? 'Trust seeker' : 'Chercheur de confiance',
        budget: isAr ? 'حساس للميزانية' : isEn ? 'Budget-sensitive buyer' : 'Sensible au budget',
        expert: isAr ? 'باحث عن الخبير' : isEn ? 'Expertise seeker' : 'Chercheur d’expertise',
        first: isAr ? 'هاجم أولا' : isEn ? 'Attack first' : 'Attaquer en premier',
        nextLean: isAr ? 'التالي بعد إثبات عضوي وميزانية صغيرة' : isEn ? 'Next after organic proof with lean budget' : 'Suivant après preuve organique avec petit budget',
        nextFocused: isAr ? 'التالي إذا توفر Budget اختبار مركز' : isEn ? 'Next with a focused test budget' : 'Suivant avec budget test focalisé',
        nextPower: isAr ? 'التالي إذا توفر Budget توسع' : isEn ? 'Next with scale budget' : 'Suivant avec budget de scale'
    };
    const fallbackSegments = [
        {
            id: 'persona-high-intent',
            name: `${labels.highIntent} · ${market}`,
            need: isAr ? `يريد ${offer} بسرعة وبأقل مخاطرة` : isEn ? `Wants ${offer} quickly with less risk` : `Veut ${offer} vite avec moins de risque`,
            accessChannels: channels.length ? channels : ['SEO', 'landing page', 'WhatsApp'],
            buyingTriggers: isAr ? ['سرعة القرار', 'وضوح العرض', 'نتيجة واضحة'] : isEn ? ['speed to decision', 'clear offer', 'visible outcome'] : ['rapidité de décision', 'offre claire', 'résultat visible'],
            confidence: 'MEDIUM'
        },
        {
            id: 'persona-comparator',
            name: `${labels.comparator} · SERP`,
            need: isAr ? 'يقارن المنافسين قبل أن يثق' : isEn ? 'Compares competitors before trusting' : 'Compare les concurrents avant de faire confiance',
            accessChannels: ['SERP', 'comparison page', 'reviews'],
            buyingTriggers: isAr ? ['السعر', 'البدائل', 'الشروط'] : isEn ? ['price', 'alternatives', 'terms'] : ['prix', 'alternatives', 'conditions'],
            confidence: 'MEDIUM'
        },
        {
            id: 'persona-proof-seeker',
            name: `${labels.trust} · ${market}`,
            need: isAr ? 'يريد اطمئنانا قبل ترك بياناته أو الشراء' : isEn ? 'Needs reassurance before submitting details or buying' : 'Veut être rassuré avant de laisser ses infos ou acheter',
            accessChannels: channels.length ? channels : ['case studies', 'social proof', 'retargeting'],
            buyingTriggers: isAr ? ['آراء العملاء', 'الضمان', 'قبل/بعد'] : isEn ? ['reviews', 'guarantee', 'before/after'] : ['avis', 'garantie', 'avant/après'],
            confidence: 'MEDIUM'
        },
        {
            id: 'persona-budget-sensitive',
            name: `${labels.budget} · ${market}`,
            need: isAr ? 'يريد أفضل قيمة بدون مخاطرة مالية' : isEn ? 'Wants best value without financial risk' : 'Cherche la meilleure valeur sans risque financier',
            accessChannels: ['offer page', 'pricing page', 'WhatsApp'],
            buyingTriggers: isAr ? ['السعر', 'الدفع', 'العرض'] : isEn ? ['price', 'payment', 'offer'] : ['prix', 'paiement', 'offre'],
            confidence: 'LOW'
        },
        {
            id: 'persona-expertise-seeker',
            name: `${labels.expert} · ${market}`,
            need: isAr ? 'يريد اختيار حل يبدو أكثر خبرة وتنظيما' : isEn ? 'Wants the solution that looks most expert and structured' : 'Cherche la solution la plus experte et structurée',
            accessChannels: archetype === 'b2b_service' ? ['LinkedIn', 'case studies', 'direct outreach'] : ['content', 'FAQ', 'comparison'],
            buyingTriggers: isAr ? ['الخبرة', 'التخصص', 'وضوح المنهج'] : isEn ? ['expertise', 'specialization', 'clear method'] : ['expertise', 'spécialisation', 'méthode claire'],
            confidence: 'LOW'
        }
    ];

    const merged = [];
    [...(segments || []), ...fallbackSegments].forEach(segment => {
        if (!segment?.id || merged.some(item => item.id === segment.id)) return;
        merged.push(segment);
    });

    if (beachheadMarket?.segmentId) {
        merged.sort((a, b) => (a.id === beachheadMarket.segmentId ? -1 : b.id === beachheadMarket.segmentId ? 1 : 0));
    }

    const competitorCount = Number(competitorData?.top10Competitors?.length || competitorData?.competitors?.length || 0);
    const sourceCount = Number(competitorData?.observedUrls?.length || competitorData?.marketSources?.length || 0);
    const keywordCount = Number((competitorData?.keywordStrategy?.primary || []).length + (competitorData?.keywordStrategy?.longTail || []).length);
    let targetCount = 3;
    if (segments.length >= 4 || competitorCount >= 5 || keywordCount >= 5) targetCount = 4;
    if (segments.length >= 5 || competitorCount >= 8 || keywordCount >= 8) targetCount = 5;
    if (sourceCount >= 10 && competitorCount >= 8) targetCount = 6;
    if (sourceCount >= 14 && keywordCount >= 10) targetCount = 7;
    targetCount = Math.min(targetCount, merged.length, 7);

    const icons = ['fa-user-tie', 'fa-user-check', 'fa-user-shield', 'fa-user-clock', 'fa-user-gear', 'fa-user-graduate', 'fa-user-tag'];
    const tones = ['34,211,238', '34,197,94', '139,92,246', '245,158,11', '236,72,153', '59,130,246', '248,113,113'];
    const ageRanges = {
        b2b_service: ['28-45', '32-55', '26-40', '30-50', '35-60', '24-38', '40-60'],
        ecommerce_product: ['22-44', '25-50', '20-38', '28-55', '18-34', '35-60', '24-45'],
        local_service: ['25-55', '30-60', '22-45', '35-65', '24-50', '28-58', '40-70'],
        content_education: ['18-35', '22-44', '25-50', '16-30', '30-55', '20-40', '35-60'],
        general_market: ['24-45', '28-55', '22-40', '30-60', '18-34', '35-58', '25-50']
    };
    const personaNames = {
        ar: ['أمين صاحب القرار', 'ليلى الباحثة عن الدليل', 'يوسف المقارن', 'سارة محدودة الميزانية', 'هند الباحثة عن الخبير', 'مروان سريع القرار', 'نادية صاحبة التوسع'],
        en: ['Amina the Decision Maker', 'Leila the Proof Seeker', 'Youssef the Comparator', 'Sara the Budget Guardian', 'Hind the Expertise Buyer', 'Marwan the Fast Mover', 'Nadia the Scale Buyer'],
        fr: ['Amina la décideuse', 'Leila chercheuse de preuve', 'Youssef le comparateur', 'Sara budget prudent', 'Hind acheteuse d’expertise', 'Marwan décision rapide', 'Nadia croissance et scale']
    };
    const personaRoles = {
        b2b_service: isAr
            ? ['مدير مشروع', 'صاحبة شركة', 'مسؤول تسويق', 'مؤسس بميزانية محدودة', 'مديرة عمليات', 'Freelance B2B', 'مدير نمو']
            : isEn
                ? ['Project owner', 'Company founder', 'Marketing lead', 'Lean-budget founder', 'Operations manager', 'B2B freelancer', 'Growth lead']
                : ['Dirigeant de projet', 'Fondatrice', 'Responsable marketing', 'Fondateur petit budget', 'Responsable opérations', 'Freelance B2B', 'Responsable croissance'],
        ecommerce_product: isAr
            ? ['مشتري جاهز', 'متسوّقة مقارنة', 'باحث عن الثقة', 'مشتري حساس للسعر', 'مستخدم يريد نتيجة', 'مشتري واتساب', 'عميل تكرار']
            : isEn
                ? ['Ready buyer', 'Comparison shopper', 'Trust seeker', 'Price-sensitive buyer', 'Outcome seeker', 'WhatsApp buyer', 'Repeat buyer']
                : ['Acheteur prêt', 'Comparatrice', 'Chercheur de confiance', 'Acheteur sensible au prix', 'Chercheur de résultat', 'Acheteur WhatsApp', 'Client réachat'],
        local_service: isAr
            ? ['عميل محلي عاجل', 'باحث خرائط', 'مقارن أسعار', 'طالب ضمان', 'صاحب توصية', 'عميل قريب', 'مشتري خدمة متكررة']
            : isEn
                ? ['Urgent local buyer', 'Maps searcher', 'Price comparer', 'Guarantee seeker', 'Referral-led buyer', 'Nearby buyer', 'Repeat service buyer']
                : ['Client local urgent', 'Chercheur Maps', 'Comparateur prix', 'Chercheur garantie', 'Client par recommandation', 'Client de proximité', 'Client récurrent'],
        content_education: isAr
            ? ['متعلم مبتدئ', 'مقارن الدورات', 'طالب شهادة', 'باحث عن تطبيق', 'صاحب تحول مهني', 'متابع محتوى', 'مشتري برنامج']
            : isEn
                ? ['Beginner learner', 'Course comparer', 'Certificate seeker', 'Practice seeker', 'Career switcher', 'Content follower', 'Program buyer']
                : ['Apprenant débutant', 'Comparateur de formations', 'Chercheur certification', 'Chercheur pratique', 'Reconvertion professionnelle', 'Abonné contenu', 'Acheteur programme'],
        general_market: isAr
            ? ['عميل عالي النية', 'مقارن البدائل', 'طالب الثقة', 'حساس للميزانية', 'باحث عن الخبير', 'سريع القرار', 'مشتري توسع']
            : isEn
                ? ['High-intent buyer', 'Alternative comparer', 'Trust seeker', 'Budget-sensitive buyer', 'Expertise seeker', 'Fast decision maker', 'Scale buyer']
                : ['Acheteur haute intention', 'Comparateur d’alternatives', 'Chercheur de confiance', 'Sensible au budget', 'Chercheur d’expertise', 'Décideur rapide', 'Acheteur scale']
    };
    const budgetTier = inferStpBudgetTier(inputs.budget);
    const budgetLabel = (index) => {
        if (index === 0) return labels.first;
        if (budgetTier === 'lean') return labels.nextLean;
        if (budgetTier === 'power') return labels.nextPower;
        return labels.nextFocused;
    };
    const attackAngleFor = (segment, index) => {
        const text = `${segment?.id || ''} ${segment?.name || ''} ${segment?.need || ''}`.toLowerCase();
        if (index === 0) return beachheadMarket?.accessPath || (isAr ? 'ابدأ برسالة دقيقة وقناة وصول واحدة' : isEn ? 'Start with one sharp message and one access channel' : 'Commencer par un message précis et un canal d’accès');
        if (/compar|price|prix|سعر|budget/.test(text)) return isAr ? 'هاجمه بصفحة مقارنة وسعر وشروط واضحة' : isEn ? 'Attack with comparison, price clarity and terms' : 'Attaquer par comparaison, prix clair et conditions';
        if (/proof|trust|avis|review|ثقة|دليل/.test(text)) return isAr ? 'هاجمه بالاطمئنان والضمان والاعتراضات' : isEn ? 'Attack with reassurance, guarantee and objections' : 'Attaquer par réassurance, garantie et objections';
        if (/agency|b2b|expert|service|وكالة|خبير/.test(text)) return isAr ? 'هاجمه بسلطة الخبرة وحالة استخدام واضحة' : isEn ? 'Attack with expertise authority and use case' : 'Attaquer par autorité experte et cas d’usage';
        return isAr ? 'هاجمه بوعد أكثر وضوحا ودليل أسرع' : isEn ? 'Attack with a clearer promise and faster proof' : 'Attaquer avec une promesse plus claire et une preuve plus rapide';
    };

    return merged.slice(0, targetCount).map((segment, index) => {
        const persona = buildStpPersona(segment, inputs, competitorData, lang);
        const score = Number(segment?.scores?.total || Math.max(44, 78 - index * 7));
        const segmentChannels = stpArray(segment.accessChannels || channels, 5);
        const attackChannels = segmentChannels.map(channel => classifyStpAttackChannel(channel, lang));
        const triggers = stpArray(segment.buyingTriggers || segment.evidence, 5);
        const pains = stpArray(persona.pains, 4);
        const attackAngle = attackAngleFor(segment, index);
        const langKey = isAr ? 'ar' : isEn ? 'en' : 'fr';
        const ageRange = ageRanges[archetype]?.[index] || ageRanges.general_market[index] || '25-50';
        const displayName = personaNames[langKey]?.[index] || `${isAr ? 'Persona' : 'Persona'} ${index + 1}`;
        const occupation = personaRoles[archetype]?.[index] || personaRoles.general_market[index] || '';
        const segmentName = segment.name || persona.name || '';
        const socialChannels = attackChannels
            .filter(channel => /social|paid|owned|inbound|outbound/i.test(`${channel?.type || ''} ${channel?.name || ''}`))
            .slice(0, 4);
        const socialPlan = {
            platforms: stpArray(socialChannels.map(channel => channel.name), 4),
            approach: index === 0
                ? (isAr ? 'ابدأ بمحتوى توضيحي قصير ثم أعد استهداف من يتفاعل.' : isEn ? 'Start with short demonstration content, then retarget engaged visitors.' : 'Commencer par du contenu démonstration court, puis recibler les visiteurs engagés.')
                : /compar|price|prix|سعر|budget/i.test(`${segment?.id || ''} ${segment?.name || ''}`)
                    ? (isAr ? 'استعمل مقارنة وسعر وشروط واضحة كزاوية محتوى.' : isEn ? 'Use comparison, price and terms as the content angle.' : 'Utiliser comparaison, prix et conditions comme angle contenu.')
                    : (isAr ? 'استعمل اعتراضاته كمواضيع محتوى ورسائل تواصل.' : isEn ? 'Turn objections into content themes and outreach messages.' : 'Transformer ses objections en contenus et messages de prospection.'),
            contentAngles: stpArray([
                attackAngle,
                ...(triggers || []),
                ...(pains || [])
            ], 5)
        };
        return {
            id: segment.id || `persona-${index + 1}`,
            number: index + 1,
            avatar: `P${index + 1}`,
            icon: icons[index] || 'fa-user',
            tone: tones[index] || '34,211,238',
            title: displayName,
            displayName,
            occupation,
            segmentName,
            role: isAr ? `Persona ${index + 1}` : isEn ? `Persona ${index + 1}` : `Persona ${index + 1}`,
            ageRange,
            summary: persona.jobToBeDone,
            market,
            priorityScore: clamp(Math.round(score), 0, 100),
            beachheadPriority: {
                rank: index + 1,
                firstToAttack: index === 0,
                budgetPath: budgetLabel(index),
                reason: index === 0 ? beachheadMarket?.rationale || segment.need : segment.need
            },
            attackAngle,
            confidence: segment.confidence || persona.confidence || 'MEDIUM',
            details: {
                need: segment.need || persona.jobToBeDone,
                primaryJobToBeDone: persona.jobToBeDone,
                ageRange,
                occupation,
                segmentName,
                attackAngle,
                budgetPath: budgetLabel(index),
                channels: segmentChannels,
                attackChannels,
                socialPlan,
                stp: {
                    segmentation: segmentName,
                    targeting: persona.name || persona.jobToBeDone,
                    positioning: attackAngle
                },
                buyingTriggers: triggers,
                pains,
                objections: stpArray(persona.objections, 4),
                proofNeeded: stpArray(persona.proofNeeded || defaultProof, 4),
                competitors: knownCompetitors.slice(0, 4),
                constraints: constraints.slice(0, 4)
            },
            evidence: stpArray([
                ...(segment.evidence || []),
                knownCompetitors.length ? `Competitors: ${knownCompetitors.slice(0, 3).join(', ')}` : '',
                channels.length ? `Channels: ${channels.slice(0, 3).join(', ')}` : ''
            ], 5)
        };
    });
}

function buildStpPositioning({ segment, persona, competitorData = {}, inputs = {}, lang = 'fr' }) {
    const isAr = lang === 'ar';
    const isEn = lang === 'en';
    const query = localizeStpSubjectForReport(inputs.query || competitorData?.query, lang) || stpText(inputs.query || competitorData?.query, 140);
    const offer = localizeStpSubjectForReport(inputs.context?.offer || query, lang) || stpText(inputs.context?.offer || query, 160);
    const market = localizeCompetitorMarketName(inputs.geo || competitorData?.geo, lang);
    const leader = competitorData?.top10Competitors?.[0] || competitorData?.competitors?.[0] || {};
    const alternative = stpText((inputs.context?.knownCompetitors || [])[0] || leader.domain || leader.displayed_link || leader.link || leader.url, 120);
    const differentiator = stpText(
        competitorData?.productServiceAudit?.killShotFeature ||
        competitorData?.blueOceanStrategy?.blueOceanMoves?.[0] ||
        competitorData?.winningMove ||
        '',
        220
    );
    const proof = stpArray([
        ...(competitorData?.proofLinks || []).slice(0, 2).map(x => x.url || x),
        ...(segment?.evidence || [])
    ], 4);

    const statement = isAr
        ? `لـ ${segment?.name || 'الشريحة المختارة'} في ${market}، يتموضع "${offer}" كحل أوضح وأكثر قابلية للتحقق من ${alternative || 'البدائل الحالية'} عبر ${differentiator || 'وعد محدد مدعوم بالأدلة قبل الادعاء'}.`
        : isEn
            ? `For ${segment?.name || 'the selected segment'} in ${market}, "${offer}" should be positioned as a clearer, more verifiable alternative to ${alternative || 'current alternatives'} through ${differentiator || 'a specific proof-led promise'}.`
            : `Pour ${segment?.name || 'le segment choisi'} en ${market}, "${offer}" doit se positionner comme une alternative plus claire et vérifiable que ${alternative || 'les alternatives actuelles'} grâce à ${differentiator || 'une promesse précise soutenue par des preuves'}.`;

    return {
        statement,
        audience: segment?.name || '',
        painPoints: persona?.pains || [],
        alternatives: persona?.alternatives || [],
        differentiatedBenefits: stpArray([differentiator, competitorData?.grandSlamOfferBlueprint?.theIrresistibleOffer], 4),
        proofStatus: proof.length ? 'PARTIAL_PROOF' : 'PROOF_REQUIRED',
        proof
    };
}

function mergeStpPersonaAiOverlay(baseCards = [], aiCards = []) {
    const overlayById = new Map((aiCards || [])
        .filter(card => card && typeof card === 'object')
        .map(card => [stpText(card.id || card.personaId, 80), card])
        .filter(([id]) => id));
    return (baseCards || []).map(card => {
        const overlay = overlayById.get(card.id) || (aiCards || [])[Number(card.number || 1) - 1] || {};
        if (!overlay || typeof overlay !== 'object') return card;
        const mergedDetails = {
            ...(card.details || {}),
            ...(overlay.details && typeof overlay.details === 'object' ? overlay.details : {})
        };
        return {
            ...card,
            title: card.displayName || card.title,
            displayName: card.displayName || card.title,
            primaryAngle: card.primaryAngle,
            secondaryAngles: card.secondaryAngles,
            angleMappings: card.angleMappings,
            angleType: card.angleType,
            occupation: stpText(overlay.occupation || mergedDetails.occupation, 80) || card.occupation,
            ageRange: stpText(overlay.ageRange, 40) || card.ageRange,
            summary: stpText(overlay.summary || overlay.jobToBeDone, 360) || card.summary,
            attackAngle: stpText(overlay.attackAngle, 260) || card.attackAngle,
            confidence: ['HIGH', 'MEDIUM', 'LOW'].includes(overlay.confidence) ? overlay.confidence : card.confidence,
            details: {
                ...mergedDetails,
                need: stpText(mergedDetails.need, 260) || card.details?.need,
                primaryMarketingAngle: stpText(mergedDetails.primaryMarketingAngle, 160) || card.details?.primaryMarketingAngle,
                primaryJobToBeDone: stpText(mergedDetails.primaryJobToBeDone, 260) || card.details?.primaryJobToBeDone,
                informationBehavior: stpText(mergedDetails.informationBehavior, 260) || card.details?.informationBehavior,
                buyingBehavior: stpText(mergedDetails.buyingBehavior, 260) || card.details?.buyingBehavior,
                searchBehavior: stpText(mergedDetails.searchBehavior, 260) || card.details?.searchBehavior,
                discoveryBehavior: stpText(mergedDetails.discoveryBehavior, 260) || card.details?.discoveryBehavior,
                occupation: stpText(mergedDetails.occupation || overlay.occupation, 80) || card.details?.occupation,
                segmentName: stpText(mergedDetails.segmentName || card.segmentName, 180) || card.details?.segmentName,
                ageRange: stpText(mergedDetails.ageRange || overlay.ageRange, 40) || card.details?.ageRange,
                attackAngle: stpText(mergedDetails.attackAngle || overlay.attackAngle, 260) || card.details?.attackAngle,
                channels: stpArray(mergedDetails.channels || card.details?.channels, 6),
                attackChannels: Array.isArray(mergedDetails.attackChannels) && mergedDetails.attackChannels.length
                    ? mergedDetails.attackChannels.slice(0, 6).map(item => typeof item === 'string' ? classifyStpAttackChannel(item) : {
                        name: stpText(item.name || item.channel, 80),
                        type: stpText(item.type || 'Experiment', 40),
                        role: stpText(item.role || item.why, 160),
                        timing: stpText(item.timing || item.stage, 40)
                    }).filter(item => item.name || item.type)
                    : card.details?.attackChannels,
                buyingTriggers: stpArray(mergedDetails.buyingTriggers || mergedDetails.triggers || card.details?.buyingTriggers, 6),
                trustSources: stpArray(mergedDetails.trustSources || card.details?.trustSources, 6),
                pains: stpArray(mergedDetails.pains || card.details?.pains, 5),
                objections: stpArray(mergedDetails.objections || card.details?.objections, 5),
                proofNeeded: stpArray(mergedDetails.proofNeeded || card.details?.proofNeeded, 5),
                competitors: stpArray(mergedDetails.competitors || card.details?.competitors, 5),
                constraints: stpArray(mergedDetails.constraints || card.details?.constraints, 5)
            },
            evidence: stpArray([...(card.evidence || []), ...(overlay.evidence || []), ...(overlay.limits || [])], 7),
            aiRefined: true
        };
    });
}

function enforceStpPersonaDiversity(personaCards = [], lang = 'fr') {
    const seenSummary = new Map();
    const seenAttack = new Map();
    return (personaCards || []).map((card, index) => {
        const details = card.details || {};
        const angleName = stpText(card.primaryAngle?.name || details.primaryMarketingAngle || card.segmentName || card.displayName || `Persona ${index + 1}`, 120);
        const summary = stpText(card.summary || details.primaryJobToBeDone || details.need, 360);
        const attack = stpText(card.attackAngle || details.attackAngle || details.stp?.positioning, 360);
        const summaryKey = summary.toLowerCase();
        const attackKey = attack.toLowerCase();
        const duplicateSummary = summaryKey && seenSummary.has(summaryKey);
        const duplicateAttack = attackKey && seenAttack.has(attackKey);
        if (summaryKey) seenSummary.set(summaryKey, card.id || index);
        if (attackKey) seenAttack.set(attackKey, card.id || index);
        const summarySuffix = lang === 'ar'
            ? ` زاوية هذه الشخصية: ${angleName}.`
            : lang === 'en'
                ? ` This persona angle: ${angleName}.`
                : ` Angle spécifique de ce persona : ${angleName}.`;
        const attackSuffix = lang === 'ar'
            ? ` طبقها برسالة مخصصة لـ ${angleName}.`
            : lang === 'en'
                ? ` Apply it with messaging tailored to ${angleName}.`
                : ` À appliquer avec un message adapté à ${angleName}.`;
        const finalSummary = duplicateSummary && angleName ? stpText(`${summary}${summarySuffix}`, 420) : summary;
        const finalAttack = duplicateAttack && angleName ? stpText(`${attack}${attackSuffix}`, 420) : attack;
        return {
            ...card,
            summary: finalSummary || card.summary,
            attackAngle: finalAttack || card.attackAngle,
            details: {
                ...details,
                primaryJobToBeDone: duplicateSummary && angleName ? finalSummary : (details.primaryJobToBeDone || finalSummary),
                attackAngle: duplicateAttack && angleName ? finalAttack : (details.attackAngle || finalAttack),
                stp: {
                    ...(details.stp || {}),
                    positioning: duplicateAttack && angleName ? finalAttack : (details.stp?.positioning || finalAttack)
                }
            }
        };
    });
}

