// ⚔️ ROUTE : COMPETITORS ENDPOINT (WAR ROOM V11)
// ════════════════════════════════════════════════════════════════════
const competitorsInFlight = new Map();
const competitorBenchmarkInFlight = new Map();

function normalizeCompetitorBenchmarkResult(result, url) {
    const meta = result?.meta || {};
    const bodyText = String(result?.bodyText || result?.content?.text || '').slice(0, 12000);
    const h1 = result?.h1 || result?.copyIntel?.headlines?.h1?.[0] || result?.mainPage?.h1 || '';
    const title = result?.title || meta.title || result?.mainPage?.title || '';
    const description = result?.description || meta.description || result?.metaDescription || '';
    const wordCount = Number(result?.wordCount || result?.brand?.wordCount || bodyText.split(/\s+/).filter(Boolean).length);
    const schemaExists = Boolean(
        result?.schema?.exists ||
        result?.trustSignals?.hasSchema ||
        result?.schemaData?.count ||
        (Array.isArray(result?.jsonLd) && result.jsonLd.length)
    );

    return {
        success: result?.success !== false && Boolean(url),
        url,
        title,
        description,
        h1,
        wordCount,
        bodyText,
        meta: { title, description },
        content: { title, description, h1, wordCount, text: bodyText },
        structure: { h1: { text: h1 } },
        schema: { exists: schemaExists },
        seo: { schema: { exists: schemaExists } },
        sections: Array.isArray(result?.sectionRawBlocks)
            ? result.sectionRawBlocks.slice(0, 35)
            : Array.isArray(result?.sectionsDetailed)
                ? result.sectionsDetailed.slice(0, 35)
                : [],
        sourceJobId: result?.sourceJobId || null,
        executionLayer: result?.executionLayer || null
    };
}

function getCompetitorBenchmark(url, lang = 'fr') {
    const key = `${String(url || '').trim().toLowerCase()}|${String(lang || 'fr').toLowerCase()}`;
    const existing = competitorBenchmarkInFlight.get(key);
    if (existing) return Promise.race([
        existing,
        new Promise(resolve => setTimeout(() => resolve(null), 15000))
    ]);

    const scrapePromise = Promise.resolve()
        .then(async () => {
            if (shouldUseRailwayScraping()) {
                console.log(`[/api/competitors] Benchmark routed to Railway: ${url}`);
                const railwayResult = await scrapeUrlViaRailway(url, {
                    purpose: 'competitor-benchmark',
                    explore: true,
                    maxPages: 4,
                    maxExtraPages: 3,
                    maxDepth: 1,
                    maxClicks: 6,
                    maxButtonsPerPage: 4,
                    crawlBudgetMs: 45000,
                    timeout: 120000
                });
                return normalizeCompetitorBenchmarkResult(railwayResult, url);
            }
            return normalizeCompetitorBenchmarkResult(await scrapeSiteData(url, lang), url);
        })
        .catch(error => {
            console.warn('[/api/competitors] Benchmark scrape failed:', error.message);
            return null;
        });
    competitorBenchmarkInFlight.set(key, scrapePromise);
    scrapePromise.finally(() => {
        if (competitorBenchmarkInFlight.get(key) === scrapePromise) {
            competitorBenchmarkInFlight.delete(key);
        }
    });
    return Promise.race([
        scrapePromise,
        new Promise(resolve => setTimeout(() => resolve(null), 15000))
    ]);
}

function buildCompetitorsRequestKey({ query = '', geo = '', lang = 'fr', url = '', forceRefresh = false, context = {} }) {
     let contextKey = '';
     try {
         contextKey = JSON.stringify(context || {}).slice(0, 2000);
     } catch (_) {
         contextKey = '';
     }
     return [
         String(query).trim().toLowerCase(),
         String(geo).trim().toLowerCase(),
         String(lang).trim().toLowerCase(),
         String(url).trim().toLowerCase(),
         forceRefresh ? 'force' : 'normal',
         contextKey
     ].join('|');
 }

app.post('/api/competitors', requireAuth, requireReportQuota, persistGeneratedReport('competitors'), warRoomLimiter, async (req, res) => {
    const startTime = Date.now();
    const isProd    = process.env.NODE_ENV === 'production';
    let inFlightKey = '';
    let requestLang = 'fr';

    try {
    let {
        query,
        geo,
        lang = 'fr',
        url,
        forceRefresh = false,
        context = {}
    } = req.body || {};

    // ── PATCH 1 : Validation query ────────────────────────
    if (!query || !query.trim()) {
        return res.status(400).json({
            success: false,
            error: 'Query is required',
            message: 'Veuillez fournir un mot-clé ou une URL.'
        });
    }

    if (query.trim().length > 300) {
        return res.status(400).json({
            success: false,
            error: 'Query too long',
            message: 'Maximum 300 caractères autorisés.'
        });
    }

    // ── PATCH 2 : Validation lang + résolution geo réelle ─
    const ALLOWED_LANGS = ['fr', 'ar', 'en'];
    if (!ALLOWED_LANGS.includes(lang)) lang = 'fr';
    requestLang = lang;

    const rawGeo = String(geo || '').trim();
    const geoData = resolveSerpGeo(rawGeo || 'Morocco');
    const safeGeo = geoData.location || 'Morocco';

        // ── PATCH 3 : Validation URL anti-SSRF ───────────────
        const isValidUrl = (u) => {
            try {
                const p = new URL(u);
                return (
                    ['http:', 'https:'].includes(p.protocol) &&
                    !['localhost', '127.0.0.1', '0.0.0.0',
                      '::1', '169.254', '10.', '192.168.']
                      .some(h => p.hostname.includes(h))
                );
            } catch { return false; }
        };

        // ── PATCH 4 : forceRefresh réservé admin ─────────────
        const safeForceRefresh = Boolean(forceRefresh) && !!req.user?.isAdmin;
        const safeContext = safeUserContextFromBody(req.body);

        console.log(
    `[api/competitors] DÉMARRAGE WAR ROOM | query="${query.trim()}" | rawGeo="${rawGeo}" | resolvedGeo="${safeGeo}" | gl="${geoData.gl}" | lang="${lang}"`
);

        // 1. Scraping du site utilisateur (si fourni) pour benchmark
        let userSiteData = null;
        if (url && isValidUrl(url.trim())) {
            console.log(`[/api/competitors] Benchmark utilisateur lancé pour : ${url}`);
            try {
                const siteScrape = await getCompetitorBenchmark(url.trim(), lang);
                if (siteScrape?.success) {
                    userSiteData = siteScrape;
                    console.log(
                        `[/api/competitors] Site utilisateur OK — ` +
                        `Mots: ${siteScrape.content?.wordCount || 0}`
                    );
                }
            } catch (scrapeErr) {
                console.warn(`[/api/competitors] Erreur scraping benchmark:`, scrapeErr.message);
            }
        }

        // 2. Appel du moteur d'analyse stratégique
        // Timeout court: la route ne doit jamais laisser l'utilisateur attendre indéfiniment.
        const ROUTE_TIMEOUT  = 45000;
        const timeoutPromise = new Promise((_, reject) =>
            setTimeout(
                () => reject(new Error('ROUTE_TIMEOUT')),
                ROUTE_TIMEOUT
            )
        );

        inFlightKey = buildCompetitorsRequestKey({
            query: query.trim(),
            geo: safeGeo,
            lang,
            url: url || '',
            forceRefresh: safeForceRefresh,
            context: safeContext
        });

        let analysisPromise = competitorsInFlight.get(inFlightKey);
        if (analysisPromise) {
            console.log(`🧠 [api/competitors] IN-FLIGHT REUSE: ${inFlightKey}`);
        } else {
            analysisPromise = analyzeCompetitors(query.trim(), safeGeo, lang, userSiteData, safeForceRefresh, null, safeContext);
            competitorsInFlight.set(inFlightKey, analysisPromise);
            analysisPromise.finally(() => {
                if (competitorsInFlight.get(inFlightKey) === analysisPromise) {
                    competitorsInFlight.delete(inFlightKey);
                }
            });
        }

       const result = await Promise.race([
    analysisPromise,
    timeoutPromise
]);
        // 3. Métriques & Logs
        const elapsed = Date.now() - startTime;
        if (result.success) {
            console.log(
                `✅ [/api/competitors] TERMINÉE en ${elapsed}ms | ` +
                `source=${result.source}`
            );
        } else {
            console.warn(`❌ [/api/competitors] ÉCHEC :`, result.error);
        }

        if (typeof updateMetrics === 'function') {
            updateMetrics(req.method, req.path, result.success ? 200 : 500, elapsed);
        }

        res.json(result);

    } catch (error) {
        const elapsed = Date.now() - startTime;

        // ── PATCH 6 : Timeout → 504 propre ───────────────────
        if (error.message === 'ROUTE_TIMEOUT') {
            console.warn(`⏱️ [/api/competitors] TIMEOUT après ${elapsed}ms`);
            // Keep the active promise registered until it settles. Removing
            // it here would let the next click launch a duplicate analysis.
            if (typeof updateMetrics === 'function') {
                updateMetrics(req.method, req.path, 504, elapsed);
            }
            return res.status(504).json({
                success: false,
                error:   'TIMEOUT',
                message: requestLang === 'ar'
                    ? 'استغرق تحليل السوق وقتا طويلا. أعد المحاولة مع كلمات أكثر تحديدا أو موقع واحد للمقارنة.'
                    : requestLang === 'en'
                        ? 'Market analysis took too long. Try again with a more specific query or one benchmark URL.'
                        : 'Analyse marché trop longue. Réessayez avec une demande plus précise ou une seule URL de benchmark.'
            });
        }

        // ── PATCH 7 : Stack trace masqué en production ────────
        console.error(
            '💥 [/api/competitors] CRASH MAJEUR:',
            isProd ? error.message : error.stack
        );
        if (typeof updateMetrics === 'function') {
            updateMetrics(req.method, req.path, 500, elapsed);
        }
        res.status(500).json({
            success: false,
            error:   'INTERNAL_SERVER_ERROR',
            details: isProd ? 'Une erreur est survenue.' : error.message
        });
    }
});

