// ✅ FIX BUG 2 & 3 — Ajouter url en paramètre
function extractSEOIntel(html, pageUrl = '') {
    const $ = cheerio.load(html || '');

    const safeText = (value) => (typeof value === 'string' ? value.trim() : '');
    const unique = (arr = []) => [...new Set((arr || []).filter(Boolean))];

    const normalizeUrl = (href, baseOrigin = '', currentPageUrl = '') => {
        if (!href || typeof href !== 'string') return null;
        const raw = href.trim();
        if (!raw) return null;

        const lower = raw.toLowerCase();
        if (
            lower.startsWith('#') ||
            lower.startsWith('javascript:') ||
            lower.startsWith('mailto:') ||
            lower.startsWith('tel:') ||
            lower.startsWith('sms:') ||
            lower.startsWith('whatsapp:') ||
            lower.startsWith('data:')
        ) {
            return null;
        }

        try {
            if (raw.startsWith('//')) return new URL(`https:${raw}`).href;
            if (/^https?:\/\//i.test(raw)) return new URL(raw).href;
            if (currentPageUrl) return new URL(raw, currentPageUrl).href;
            if (baseOrigin) return new URL(raw, baseOrigin).href;
        } catch {}

        return null;
    };

    const getHostname = (url) => {
        try {
            return new URL(url).hostname.replace(/^www\./i, '').toLowerCase();
        } catch {
            return '';
        }
    };

    const isSameSite = (urlA, urlB) => {
        const a = getHostname(urlA);
        const b = getHostname(urlB);
        return !!a && !!b && a === b;
    };

    const uniqueBy = (arr = [], key) => {
        const seen = new Set();
        return arr.filter(item => {
            const val = item?.[key];
            if (!val || seen.has(val)) return false;
            seen.add(val);
            return true;
        });
    };

    const countRegex = (re, str) => {
        try {
            return (str.match(re) || []).length;
        } catch {
            return 0;
        }
    };

    const wordStatus = (count = 0) =>
        count < 200 ? 'INSUFFISANT (< 200 mots)' :
        count < 500 ? 'FAIBLE (200-500 mots)' :
        count < 1000 ? 'MOYEN (500-1000 mots)' :
        'BON (> 1000 mots)';

    const canonicalHref = safeText($('link[rel="canonical"]').attr('href'));
    const origin = (() => {
        try {
            if (pageUrl) return new URL(pageUrl).origin;
        } catch {}
        try {
            if (canonicalHref && /^https?:\/\//i.test(canonicalHref)) {
                return new URL(canonicalHref).origin;
            }
        } catch {}
        return '';
    })();

    const stopWords = new Set([
        'dans', 'avec', 'pour', 'votre', 'notre', 'leurs', 'cette',
        'tous', 'fait', 'faire', 'plus', 'être', 'avoir', 'aussi', 'comme',
        'nous', 'vous', 'elles', 'ils', 'ceci', 'cela', 'tres', 'très',
        'the', 'of', 'and', 'in', 'to', 'for', 'a', 'an', 'is', 'are',
        'was', 'this', 'that', 'le', 'la', 'les', 'de', 'des', 'un', 'une',
        'et', 'en', 'au', 'du', 'ce', 'est', 'sur', 'nos', 'par', 'que',
        'qui', 'je', 'il',
        'من', 'في', 'على', 'هذا', 'هذه', 'مع', 'هو', 'هي', 'أن', 'إلى', 'عن', 'كان'
    ]);

    const bodyTextRaw = $('body').text().replace(/\s+/g, ' ').trim();
    const bodyText = bodyTextRaw.toLowerCase();

    const words = bodyText
        .split(/\s+/)
        .map(w => w.replace(/[^\p{L}\p{N}-]/gu, ''))
        .filter(w =>
            w.length > 3 &&
            !stopWords.has(w) &&
            /[a-z\u00C0-\u024F\u0600-\u06FF]/i.test(w)
        );

    const totalWords = words.length || 1;
    const wordFreq = {};
    words.forEach(w => {
        wordFreq[w] = (wordFreq[w] || 0) + 1;
    });

    const topKeywords = Object.entries(wordFreq)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 25)
        .map(([word, count]) => ({
            word,
            keyword: word,
            count,
            density: parseFloat(((count / totalWords) * 100).toFixed(2))
        }));

    const title = safeText($('title').text());
    const description = safeText($('meta[name="description" i]').attr('content'));
    const h1Text = safeText($('h1').first().text());
    const h1Count = $('h1').length;
    const h2s = unique($('h2').map((i, el) => safeText($(el).text())).get()).slice(0, 12);
    const h3s = unique($('h3').map((i, el) => safeText($(el).text())).get()).slice(0, 12);

    const titleLength = title.length;
    const descriptionLength = description.length;

    const canonical = canonicalHref || null;
    const viewport = safeText($('meta[name="viewport"]').attr('content'));
    const robots = safeText($('meta[name="robots" i]').attr('content')) || null;
    const lang = safeText($('html').attr('lang')) || null;

    const ogTitle = safeText($('meta[property="og:title"]').attr('content')) || null;
    const ogDescription = safeText($('meta[property="og:description"]').attr('content')) || null;
    const ogImage = safeText($('meta[property="og:image"]').attr('content')) || null;
    const keywords = safeText($('meta[name="keywords" i]').attr('content')) || null;
    const twitterCard = safeText($('meta[name="twitter:card" i]').attr('content')) || null;

    const schemaBlocks = $('script[type="application/ld+json"]');
    const schemaTypes = [];

    schemaBlocks.each((i, el) => {
        try {
            const raw = $(el).html();
            if (!raw) return;
            const parsed = JSON.parse(raw);

            const collectType = (node) => {
                if (!node) return;
                if (Array.isArray(node)) {
                    node.forEach(collectType);
                    return;
                }
                if (typeof node !== 'object') return;

                if (node['@type']) {
                    if (Array.isArray(node['@type'])) {
                        node['@type'].forEach(t => schemaTypes.push(String(t)));
                    } else {
                        schemaTypes.push(String(node['@type']));
                    }
                }

                if (Array.isArray(node['@graph'])) {
                    node['@graph'].forEach(collectType);
                }
            };

            collectType(parsed);
        } catch {}
    });

    const cleanSchemaTypes = unique(schemaTypes);

    const issues = [];

    if (!title) {
        issues.push({ severity: 'HIGH', field: 'title', issue: 'Title manquant — suicide SEO' });
    } else if (titleLength < 30) {
        issues.push({ severity: 'HIGH', field: 'title', issue: `Title trop court (${titleLength} chars < 30)` });
    } else if (titleLength > 65) {
        issues.push({ severity: 'MEDIUM', field: 'title', issue: `Title trop long (${titleLength} chars > 65)` });
    }

    if (!description) {
        issues.push({ severity: 'HIGH', field: 'description', issue: 'Meta description absente' });
    } else if (descriptionLength < 70) {
        issues.push({ severity: 'MEDIUM', field: 'description', issue: `Description trop courte (${descriptionLength} chars)` });
    } else if (descriptionLength > 165) {
        issues.push({ severity: 'LOW', field: 'description', issue: `Description trop longue (${descriptionLength} chars > 165)` });
    }

    if (h1Count === 0) {
        issues.push({ severity: 'HIGH', field: 'h1', issue: 'H1 absent' });
    } else if (h1Count > 1) {
        issues.push({ severity: 'MEDIUM', field: 'h1', issue: `${h1Count} H1 détectés — doit être unique` });
    }

    const missingAlt = $('img:not([alt]), img[alt=""]').length;
    if (missingAlt > 0) {
        issues.push({ severity: 'MEDIUM', field: 'images', issue: `${missingAlt} image(s) sans ALT` });
    }

    if (!canonical) {
        issues.push({ severity: 'MEDIUM', field: 'canonical', issue: 'Canonical absent' });
    }

    if (!viewport) {
        issues.push({ severity: 'HIGH', field: 'mobile', issue: 'Viewport absent — pénalité Google' });
    }

    if (!ogTitle) {
        issues.push({ severity: 'LOW', field: 'opengraph', issue: 'og:title absent' });
    }

    if (schemaBlocks.length === 0) {
        issues.push({ severity: 'MEDIUM', field: 'schema', issue: 'Schema.org absent' });
    }

    const highIssues = issues.filter(i => i.severity === 'HIGH').length;
    const mediumIssues = issues.filter(i => i.severity === 'MEDIUM').length;
    const lowIssues = issues.filter(i => i.severity === 'LOW').length;

    const seoScore = Math.max(
        0,
        Math.min(100, Math.round(100 - (highIssues * 20) - (mediumIssues * 8) - (lowIssues * 3)))
    );

    const seoGrade =
        seoScore >= 90 ? 'A+' :
        seoScore >= 80 ? 'A' :
        seoScore >= 70 ? 'B' :
        seoScore >= 60 ? 'C' :
        seoScore >= 45 ? 'D' : 'F';

    const hreflang = unique(
        $('link[rel="alternate"][hreflang]')
            .map((i, el) => safeText($(el).attr('hreflang')))
            .get()
    );

    const hasSchema = schemaBlocks.length > 0;
    const hasFAQ =
        $('[itemtype*="FAQPage"], .faq, #faq, [class*="faq"], details, summary').length > 0 ||
        /faq|frequently\s+asked|questions?\s+fr[ée]quentes?/i.test(html || '');

    const hasHowTo =
        $('[itemtype*="HowTo"]').length > 0 ||
        /how.to|étapes/i.test(html || '');

    const hasDefinitions = $('dt, dfn').length > 0;

    const aeoSignals = {
        hasFAQ,
        hasHowTo,
        hasDefinitions,
        hasSchema,
        score: [hasFAQ, hasHowTo, hasDefinitions, hasSchema].filter(Boolean).length,
        aiCompatibility: {
            chatgpt: hasSchema && hasFAQ ? 'GOOD' : 'WEAK',
            gemini: hasSchema ? 'GOOD' : 'WEAK',
            perplexity: hasFAQ && words.length > 300 ? 'GOOD' : 'WEAK'
        }
    };

    const scriptCount = $('script[src]').length;
    const inlineScriptCount = $('script:not([src])').length;
    const externalScripts = $('script[src]').length;
    const cssCount = $('link[rel="stylesheet"]').length;
    const cssFiles = cssCount;
    const hasMinified = /\.min\.js|\.min\.css/i.test(html || '');
    const hasServiceWorker = /serviceworker/i.test(html || '');
    const hasCDN = /cloudflare|cloudfront|fastly|akamai|jsdelivr|unpkg|cdn\./i.test(html || '');
    const hasPreload = $('link[rel="preload"], link[rel="prefetch"], link[rel="preconnect"]').length > 0;
    const hasSSL = pageUrl ? /^https:\/\//i.test(pageUrl) : /^https:\/\//i.test(canonicalHref || '');
    const charset =
        safeText($('meta[charset]').attr('charset')) ||
        (($('meta[http-equiv="Content-Type"]').attr('content') || '').match(/charset=([^\s;]+)/i)?.[1] || null);

    const hasVideo =
        $('video').length > 0 ||
        $('iframe[src*="youtube"], iframe[src*="youtu.be"], iframe[src*="vimeo"], iframe[src*="dailymotion"]').length > 0 ||
        /\.(mp4|webm|ogg)/i.test(html || '');

    const imgTags = $('img').length;
    const imgDataSrc = $('img[data-src], img[data-lazy-src], img[data-original]').length;
    const bgImages = countRegex(/url\((['"]?)(https?:)?[^)]+\.(png|jpg|jpeg|webp|gif|svg)\1\)/gi, html || '');
    const totalImages = imgTags + imgDataSrc + bgImages;
    const webpImages =
        $('img[src$=".webp"], source[srcset*=".webp"], source[type="image/webp"]').length +
        countRegex(/\.webp/gi, html || '');
    const lazyLoadImages =
        $('img[loading="lazy"], img[data-src], img[data-lazy-src], img[data-original]').length;

    const hasExitIntent = /exit[-\s_]?intent|mouseleave|beforeunload/i.test(html || '');
    const hasPopup = /modal|popup|lightbox|overlay/i.test(html || '');
    const hasCountdown = /countdown|timer|count-?down|compte-?.?rebours/i.test(html || '');
    const hasStickyCTA = /sticky|fixed-bottom|fixed-top/i.test(html || '');
    const hasLiveChat = /tawk|intercom|crisp|tidio|zendesk|freshchat/i.test(html || '');
    const hasWhatsApp = /wa\.me|whatsapp/i.test(html || '');
    const hasCOD = /cash[-\s]?on[-\s]?delivery|contre[-\s]?remboursement|paiement[-\s]?livraison/i.test(html || '');

    const allAnchors = $('a[href]').map((i, el) => {
        const href = safeText($(el).attr('href'));
        const text = safeText($(el).text()).replace(/\s+/g, ' ');
        const normalized = normalizeUrl(href, origin, pageUrl);
        const rel = safeText($(el).attr('rel'))
            .toLowerCase()
            .split(/\s+/)
            .filter(Boolean);
        const context = safeText(
            $(el).closest('p, li, article, section, nav, footer, header').first().text()
        ).replace(/\s+/g, ' ').substring(0, 240);

        const isInternal =
            !!normalized &&
            (
                href.startsWith('/') ||
                (origin ? isSameSite(normalized, origin) : false)
            );

        const isExternal = !!normalized && !isInternal;

        return {
            href,
            text: text || null,
            anchor: text || null,
            anchorText: text || null,
            normalized,
            url: normalized,
            sourceUrl: pageUrl || canonical || origin || null,
            targetUrl: normalized,
            isInternal,
            isExternal,
            linkType: isInternal ? 'INTERNAL' : isExternal ? 'OUTBOUND' : 'IGNORED',
            rel,
            nofollow: rel.includes('nofollow'),
            sponsored: rel.includes('sponsored'),
            ugc: rel.includes('ugc'),
            targetBlank: safeText($(el).attr('target')).toLowerCase() === '_blank',
            context: context || null,
            status: normalized ? 'NOT_CHECKED' : 'IGNORED'
        };
    }).get();

    const internalLinkObjects = uniqueBy(
        allAnchors.filter(x => x.normalized && x.isInternal),
        'normalized'
    ).slice(0, 30);

    const externalOutboundLinkObjects = uniqueBy(
        allAnchors.filter(x => x.normalized && x.isExternal),
        'normalized'
    ).slice(0, 30);

    const brokenLinkObjects = allAnchors
        .filter(x => !x.href || x.href === '#' || /^javascript:\s*(?:void\(0\))?;?$/i.test(x.href))
        .map(x => ({
            url: pageUrl,
            sourceUrl: pageUrl,
            href: x.href || '',
            text: x.text || 'Lien sans libellé',
            status: 'BROKEN_ANCHOR'
        }))
        .filter((item, index, list) =>
            list.findIndex(other => other.href === item.href && other.text === item.text) === index
        )
        .slice(0, 20);

    const internalLinks = internalLinkObjects.map(x => x.normalized);
    const externalOutboundLinks = externalOutboundLinkObjects.map(x => x.normalized);
    const externalLinks = externalOutboundLinks;

    const linkSummary = {
        totalAnchors: allAnchors.length,
        internalCount: uniqueBy(allAnchors.filter(x => x.normalized && x.isInternal), 'normalized').length,
        externalOutboundCount: uniqueBy(allAnchors.filter(x => x.normalized && x.isExternal), 'normalized').length,
        ignoredCount: allAnchors.filter(x => !x.normalized).length
    };

    const paragraphs = $('p').length;
    const listCount = $('ul, ol').length;
    const buttonCount = $('button, a.btn, a.button, .cta').length;
    const wordCount = totalWords;
    const contentStatus = wordStatus(wordCount);

    const technicalSummary = {
        meta: {
            titleLength,
            descriptionLength,
            hasCanonical: !!canonical,
            hasRobots: !!robots,
            hasViewport: !!viewport,
            hasOG: !!ogTitle,
            hasTwitterCard: !!twitterCard,
            lang
        },
        headings: {
            h1Count,
            h2Count: $('h2').length,
            h3Count: $('h3').length
        },
        content: {
            wordCount,
            paragraphs,
            listCount,
            buttonCount,
            contentStatus
        },
        media: {
            totalImages,
            missingAlt,
            webpImages,
            lazyLoadImages,
            hasVideo
        },
        links: linkSummary,
        structuredData: {
            hasSchema,
            schemaCount: schemaBlocks.length,
            schemaTypes: cleanSchemaTypes
        },
        performance: {
            scriptCount,
            inlineScriptCount,
            externalScripts,
            cssCount,
            cssFiles,
            hasMinified,
            hasServiceWorker,
            hasCDN,
            hasPreload,
            hasSSL,
            charset
        },
        conversion: {
            hasFAQ,
            hasExitIntent,
            hasPopup,
            hasCountdown,
            hasStickyCTA,
            hasLiveChat,
            hasWhatsApp,
            hasCOD
        }
    };

    return {
        title,
        titleLength,
        metaDescription: description,
        description: description,
        descriptionLength,
        h1: h1Text,
        h1Count,
        h2s,
        h3s,
        headingCounts: {
            h1: h1Count,
            h2: $('h2').length,
            h3: $('h3').length
        },
        ogTitle,
        ogDescription,
        ogImage,
        twitterCard,
        robots,
        lang,
        canonical,
        hasCanonical: !!canonical,
        keywords,
        keywordsMeta: keywords ? keywords.split(',').map(k => k.trim()).filter(Boolean).slice(0, 20) : [],

        topKeywords,

        seoScore,
        seoGrade,
        issues,

        hreflang,
        hasHreflang: hreflang.length > 0,

        aeoSignals,

        schemaTypes: cleanSchemaTypes,
        schemaCount: schemaBlocks.length,
        hasSchema,

        paragraphs,
        listCount,
        buttonCount,
        wordCount,
        contentStatus,

        totalImages,
        missingAlt,
        webpImages,
        lazyLoadImages,
        hasVideo,

        scriptCount,
        inlineScriptCount,
        externalScripts,
        cssCount,
        cssFiles,
        hasMinified,
        hasServiceWorker,
        hasCDN,
        hasPreload,
        hasSSL,
        charset,

        hasFAQ,
        hasHowTo,
        hasDefinitions,
        hasExitIntent,
        hasPopup,
        hasCountdown,
        hasStickyCTA,
        hasLiveChat,
        hasWhatsApp,
        hasCOD,

        internalLinks,
        externalLinks,
        externalOutboundLinks,
        internalLinkObjects,
        externalOutboundLinkObjects,
        brokenLinkObjects,
        linkSummary,

        technicalSummary
    };
}


// ✅ VERSION DEEP — extractPerfSignals
async function verifyObservedLink(link = {}, timeoutMs = 3200) {
    const targetUrl = link.targetUrl || link.normalized || link.url || link.href;
    if (!isPublicHttpUrl(targetUrl)) {
        return { ...link, targetUrl: targetUrl || null, status: 'UNVERIFIED', statusCode: null };
    }

    const requestConfig = {
        timeout: timeoutMs,
        maxRedirects: 5,
        validateStatus: () => true,
        headers: {
            'User-Agent': 'Mozilla/5.0 (compatible; DakaLinkAudit/1.0)',
            'Accept': 'text/html,application/xhtml+xml'
        }
    };

    try {
        let response = await axios.head(targetUrl, requestConfig);
        if ([403, 405, 406].includes(response.status)) {
            response = await axios.get(targetUrl, {
                ...requestConfig,
                headers: { ...requestConfig.headers, Range: 'bytes=0-1024' },
                maxContentLength: 64 * 1024
            });
        }
        const statusCode = Number(response.status) || null;
        const status =
            statusCode >= 200 && statusCode < 300 ? 'OK' :
            statusCode >= 300 && statusCode < 400 ? 'REDIRECT' :
            statusCode >= 400 ? 'BROKEN' : 'UNVERIFIED';
        return {
            ...link,
            targetUrl,
            url: link.url || targetUrl,
            status,
            statusCode,
            finalUrl: response.request?.res?.responseUrl || targetUrl
        };
    } catch (error) {
        return {
            ...link,
            targetUrl,
            url: link.url || targetUrl,
            status: 'UNVERIFIED',
            statusCode: null,
            error: String(error.message || 'LINK_CHECK_FAILED').substring(0, 180)
        };
    }
}

async function discoverVerifiedInboundLinks(targetUrl, options = {}) {
    const maxCandidates = Math.max(1, Math.min(Number(options.maxCandidates) || 5, 8));
    const cacheHost = (() => {
        try { return new URL(targetUrl).hostname.replace(/^www\./i, '').toLowerCase(); }
        catch { return ''; }
    })();
    if (!cacheHost || !process.env.SERPER_API_KEY) {
        return { links: [], source: 'unavailable', candidatesChecked: 0 };
    }

    const cacheKey = `verified-inbound-v1:${cacheHost}`;
    const cached = cache.get(cacheKey);
    if (cached) return cached;

    try {
        const searchResponse = await axios.post(
            'https://google.serper.dev/search',
            { q: `"${cacheHost}" -site:${cacheHost}`, num: maxCandidates + 3 },
            {
                headers: {
                    'X-API-KEY': process.env.SERPER_API_KEY,
                    'Content-Type': 'application/json'
                },
                timeout: 4500
            }
        );

        const candidates = (searchResponse.data?.organic || [])
            .map(item => ({
                sourceUrl: item.link,
                sourceTitle: item.title || null,
                sourceSnippet: item.snippet || null
            }))
            .filter(item => {
                if (!isPublicHttpUrl(item.sourceUrl)) return false;
                try {
                    return new URL(item.sourceUrl).hostname.replace(/^www\./i, '').toLowerCase() !== cacheHost;
                } catch {
                    return false;
                }
            })
            .slice(0, maxCandidates);

        const checked = await Promise.allSettled(candidates.map(async candidate => {
            const response = await axios.get(candidate.sourceUrl, {
                timeout: 4000,
                maxRedirects: 4,
                maxContentLength: 900 * 1024,
                headers: {
                    'User-Agent': 'Mozilla/5.0 (compatible; DakaLinkAudit/1.0)',
                    'Accept': 'text/html,application/xhtml+xml'
                }
            });
            const $ = cheerio.load(typeof response.data === 'string' ? response.data : '');
            const found = [];
            $('a[href]').each((_, el) => {
                const href = String($(el).attr('href') || '').trim();
                let resolved;
                try { resolved = new URL(href, candidate.sourceUrl); } catch { return; }
                if (resolved.hostname.replace(/^www\./i, '').toLowerCase() !== cacheHost) return;
                const rel = String($(el).attr('rel') || '').toLowerCase().split(/\s+/).filter(Boolean);
                found.push({
                    url: candidate.sourceUrl,
                    sourceUrl: candidate.sourceUrl,
                    targetUrl: resolved.href,
                    anchor: String($(el).text() || '').replace(/\s+/g, ' ').trim() || cacheHost,
                    sourceTitle: candidate.sourceTitle,
                    sourceSnippet: candidate.sourceSnippet,
                    linkType: 'INBOUND',
                    rel,
                    nofollow: rel.includes('nofollow'),
                    sponsored: rel.includes('sponsored'),
                    ugc: rel.includes('ugc'),
                    status: 'VERIFIED_INBOUND',
                    source: 'external-page-verified'
                });
            });
            return found;
        }));

        const seen = new Set();
        const links = checked
            .flatMap(result => result.status === 'fulfilled' ? result.value : [])
            .filter(link => {
                const key = `${link.sourceUrl}|${link.targetUrl}`.toLowerCase();
                if (seen.has(key)) return false;
                seen.add(key);
                return true;
            })
            .slice(0, 20);

        const result = {
            links,
            source: 'external-pages-verified',
            candidatesChecked: candidates.length,
            discoveredAt: new Date().toISOString()
        };
        cache.set(cacheKey, result);
        return result;
    } catch (error) {
        console.warn('[LinkIntel] Inbound discovery error:', error.message);
        return { links: [], source: 'error', candidatesChecked: 0, error: error.message };
    }
}

async function buildLinkIntelligence(seoIntel = {}, targetUrl = '') {
    const normalizeLinkItem = (item = {}, fallbackType = 'OUTBOUND') => {
        const rawUrl = typeof item === 'string'
            ? item
            : (item.url || item.normalized || item.targetUrl || item.href || item.link || item.sourceUrl || '');
        if (!rawUrl) return null;

        let resolved = '';
        try {
            resolved = new URL(String(rawUrl), targetUrl || undefined).href;
        } catch {
            return null;
        }
        if (!isPublicHttpUrl(resolved)) return null;

        const rel = Array.isArray(item.rel)
            ? item.rel.filter(Boolean)
            : String(item.rel || '').toLowerCase().split(/\s+/).filter(Boolean);

        return {
            url: resolved,
            normalized: resolved,
            href: typeof item === 'object' ? (item.href || resolved) : resolved,
            sourceUrl: item.sourceUrl || targetUrl || null,
            targetUrl: item.targetUrl || resolved,
            anchor: item.anchor || item.anchorText || item.text || item.title || null,
            text: item.text || item.anchor || item.anchorText || null,
            context: item.context || item.sourceSnippet || null,
            linkType: item.linkType || fallbackType,
            rel,
            nofollow: item.nofollow ?? rel.includes('nofollow'),
            sponsored: item.sponsored ?? rel.includes('sponsored'),
            ugc: item.ugc ?? rel.includes('ugc'),
            status: item.status || 'NOT_CHECKED',
            statusCode: item.statusCode || item.httpStatus || null,
            source: item.source || null
        };
    };

    const uniqueLinks = (items = [], fallbackType = 'OUTBOUND', limit = 60) => {
        const seen = new Set();
        return (Array.isArray(items) ? items : [])
            .map(item => normalizeLinkItem(item, fallbackType))
            .filter(item => {
                const key = item?.url?.toLowerCase();
                if (!key || seen.has(key)) return false;
                seen.add(key);
                return true;
            })
            .slice(0, limit);
    };

    const internalLinks = uniqueLinks(
        seoIntel.internalLinkObjects || seoIntel.internalLinks || [],
        'INTERNAL',
        80
    );
    const outboundCandidates = uniqueLinks(
        seoIntel.externalOutboundLinkObjects || seoIntel.externalOutboundLinks || seoIntel.externalLinks || [],
        'OUTBOUND',
        80
    );
    const anchorBroken = (Array.isArray(seoIntel.brokenLinkObjects) ? seoIntel.brokenLinkObjects : [])
        .map(item => ({
            ...item,
            url: item.url || item.sourceUrl || targetUrl,
            targetUrl: isPublicHttpUrl(item.targetUrl || '') ? item.targetUrl : (item.url || item.sourceUrl || targetUrl),
            status: item.status || 'BROKEN_ANCHOR'
        }));

    const checkedOutbound = await Promise.allSettled(
        outboundCandidates.slice(0, 12).map(link => verifyObservedLink(link, 2200))
    );
    const verifiedOutbound = outboundCandidates.map((link, index) => {
        const checked = checkedOutbound[index];
        return checked?.status === 'fulfilled' ? checked.value : link;
    });

    const brokenFromChecks = verifiedOutbound
        .filter(link => link.status === 'BROKEN' || Number(link.statusCode) >= 400)
        .map(link => ({
            ...link,
            linkType: 'BROKEN',
            status: link.status || 'BROKEN'
        }));

    const inboundDiscovery = await discoverVerifiedInboundLinks(targetUrl, { maxCandidates: 5 });
    const inboundLinks = uniqueLinks(inboundDiscovery.links || [], 'INBOUND', 30);
    const brokenLinks = uniqueLinks([...anchorBroken, ...brokenFromChecks], 'BROKEN', 60);

    const summary = {
        totalAnchors: seoIntel.linkSummary?.totalAnchors ?? (internalLinks.length + outboundCandidates.length),
        internalCount: internalLinks.length,
        outboundCount: verifiedOutbound.length,
        inboundVerifiedCount: inboundLinks.length,
        brokenCount: brokenLinks.length,
        nofollowOutboundCount: verifiedOutbound.filter(link => link.nofollow).length,
        sponsoredOutboundCount: verifiedOutbound.filter(link => link.sponsored).length,
        checkedOutboundCount: Math.min(outboundCandidates.length, 12),
        inboundSource: inboundDiscovery.source || 'unavailable',
        candidatesChecked: inboundDiscovery.candidatesChecked || 0
    };

    return {
        summary,
        inboundLinks,
        internalLinks,
        outboundLinks: verifiedOutbound,
        brokenLinks,
        linkAudit: {
            status: brokenLinks.length ? 'ACTION_REQUIRED' : 'OK',
            observations: [
                `${summary.internalCount} internal links mapped`,
                `${summary.outboundCount} outbound links mapped`,
                `${summary.inboundVerifiedCount} verified inbound links observed`,
                `${summary.brokenCount} broken or unsafe anchors detected`
            ],
            recommendations: [
                ...(brokenLinks.length ? ['Fix, redirect or remove broken links before publishing the report.'] : []),
                ...(inboundLinks.length ? ['Preserve verified inbound sources and monitor their quality.'] : ['No verified inbound link was observed automatically; confirm backlinks manually with your preferred authority tool.']),
                ...(summary.nofollowOutboundCount ? ['Review nofollow/sponsored attributes on outbound links for business relevance.'] : [])
            ].slice(0, 4)
        }
    };
}



function extractPerfSignals(html) {
    const $ = cheerio.load(html);

    // ── IMAGES ───────────────────────────────────────────────
    const imgTags        = $('img').length;
    const imgDataSrc     = $('img[data-src], img[data-lazy-src], img[data-original]').length;
    const bgImages       = (html.match(/url\(?['"]?https?:\/\/[^'")\s]+\.(png|jpg|jpeg|webp|gif|svg)/gi) || []).length;
    const totalImages    = imgTags + imgDataSrc + bgImages;
    const missingAlt     = $('img:not([alt]), img[alt=""]').length;
    const webpImages     = $('img[src*=".webp"], source[srcset*=".webp"], source[type="image/webp"]').length
                         + (html.match(/\.webp/gi) || []).length;
    const lazyLoadImages = $('img[loading="lazy"]').length + imgDataSrc;

    // ── VIDÉO ────────────────────────────────────────────────
    const hasVideo = $('video').length > 0
        || /\.mp4|\.webm|\.ogg/i.test(html)
        || /youtube\.com|youtu\.be|vimeo\.com|dailymotion\.com/i.test(html)
        || $('iframe[src*="youtube"], iframe[src*="vimeo"]').length > 0;

    // ── FAQ ──────────────────────────────────────────────────
    const hasFAQ = /faq|frequently\s+asked|questions?\s+fr[ée]quentes?/i.test(html)
        || /أسئلة|سؤال|الأسئلة\s+الشائعة/i.test(html)
        || /accordion|collapse|toggle/i.test(html)
        || $('[class*="faq"], [id*="faq"], [class*="accordion"], [class*="collapse"], details, summary').length > 0;

    // ── SCRIPTS & CSS ─────────────────────────────────────────
    const externalScripts  = $('script[src]').length;
    const cssFiles         = $('link[rel="stylesheet"]').length;
    const hasMinified      = /\.min\.js|\.min\.css/.test(html);
    const hasServiceWorker = /serviceWorker/i.test(html);

    // ── INFRA CDN ─────────────────────────────────────────────
    const hasCDN = /cloudflare|cloudfront|fastly|akamai|jsdelivr|unpkg/i.test(html);

    // ── CONVERSION ────────────────────────────────────────────
    const hasExitIntent = /exit[\-_.]?intent|mouseleave|beforeunload/i.test(html);
    const hasPopup      = /modal|popup|lightbox|overlay/i.test(html);
    const hasCountdown  = /countdown|timer|count-?down|compte[\-.]?rebours/i.test(html);
    const hasStickyCTA  = /sticky|fixed-bottom|fixed-top/i.test(html);
    const hasLiveChat   = /tawk|intercom|crisp|tidio|zendesk|freshchat/i.test(html);
    const hasWhatsApp   = /wa\.me|whatsapp/i.test(html);
    const hasCOD        = /cash[\-.]on[\-.]delivery|contre[\-.]remboursement|paiement[\-.]livraison/i.test(html);
    const hasSSL        = /^https/i.test(html.substring(0, 500));

    return {
        totalImages, lazyLoadImages, missingAlt, webpImages,
        hasVideo, hasFAQ,
        externalScripts, cssFiles, hasMinified, hasServiceWorker,
        hasCDN, hasSSL,
        hasExitIntent, hasPopup, hasCountdown, hasStickyCTA,
        hasLiveChat, hasWhatsApp, hasCOD
    };
}

// ✅ calculateAdvancedScores
function calculateAdvancedScores(report, techStack, psychTriggers, perfSignals) {
    let seo = 0, trust = 0, conversion = 0, performance = 0, funnel = 0;

    // ── SEO ───────────────────────────────────────────────────
    seo += (report?.financialIntel?.estimatedMonthlyTraffic || 0) > 10000 ? 30 : 15;
    seo += (techStack?.analytics?.length || 0) * 10;

    // ── TRUST ─────────────────────────────────────────────────
    trust += (psychTriggers?.social_proof?.length || 0) * 10;
    trust += (psychTriggers?.guarantees?.length   || 0) * 15;
    trust += (psychTriggers?.authority?.length    || 0) * 8;
    trust += (techStack?.chat_support?.length     || 0) * 5;

    // ── CONVERSION ───────────────────────────────────────────
    conversion += (psychTriggers?.cta_buttons?.length   || 0) * 5;
    conversion += (psychTriggers?.urgency?.length        || 0) * 8;
    conversion += (psychTriggers?.scarcity?.length       || 0) * 10;
    conversion += (psychTriggers?.fear_loss?.length      || 0) * 6;
    conversion += (psychTriggers?.price_anchors?.length  || 0) * 4;
    conversion += perfSignals?.hasCountdown  ? 15 : 0;
    conversion += perfSignals?.hasExitIntent ? 10 : 0;
    conversion += perfSignals?.hasPopup      ?  5 : 0;

    // ── PERFORMANCE ───────────────────────────────────────────
    performance += perfSignals?.hasCDN                         ? 20 : 0;
    performance += (perfSignals?.lazyLoadImages  || 0) > 0     ? 15 : 0;
    performance += (perfSignals?.externalScripts || 0) < 5     ? 20
                 : (perfSignals?.externalScripts || 0) < 10    ? 10 : 0;
    performance += perfSignals?.hasServiceWorker               ? 15 : 0;

    // ── FUNNEL ────────────────────────────────────────────────
    funnel += (techStack?.payment?.length         || 0) * 20;
    funnel += (techStack?.email_marketing?.length || 0) * 15;
    funnel += (techStack?.funnel_builders?.length || 0) * 25;
    funnel += perfSignals?.hasPopup               ?  10 : 0;

    // ── CLAMP ─────────────────────────────────────────────────
    const clamp = (v) => Math.min(100, Math.max(0, v));
    seo         = clamp(seo);
    trust       = clamp(trust);
    conversion  = clamp(conversion);
    performance = clamp(performance);
    funnel      = clamp(funnel);

    const global = Math.round(
        seo        * 0.15 +
        trust      * 0.20 +
        conversion * 0.25 +
        performance* 0.15 +
        funnel     * 0.25
    );

    return { seo, trust, conversion, performance, funnel, global };
}

// ── Rate limiter Funnel Spy ────────────────────────────────────────
const analysisLimiter = rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 20,
    standardHeaders: true,
    legacyHeaders: false,
    handler: (req, res) => {
        res.status(429).json({
            success: false,
            error: 'RATE_LIMIT',
            message: 'Trop de requêtes. Réessayez dans 15 minutes.',
            retryAfter: 15
        });
    }
});







