app.get('/api/job/:id', requireAuth, async (req, res) => {
    if (!supabase) {
        return res.json({
            jobId: req.params.id,
            status: 'no_queue',
            result: null,
            error: null,
            timing: { created: null, started: null, finished: null, durationMs: null }
        });
    }

    try {
        const { data, error } = await supabase
            .from('scrape_jobs')
            .select('id,status,result,error,payload,created_at,started_at,finished_at')
            .eq('id', req.params.id)
            .single();

        if (error || !data) {
            return res.status(404).json({
                jobId: req.params.id,
                status: 'not_found',
                result: null,
                error: error?.message || 'Job not found',
                timing: { created: null, started: null, finished: null, durationMs: null }
            });
        }

        if (data.payload?._authUserId !== req.user.id) {
            return res.status(404).json({
                jobId: req.params.id,
                status: 'not_found',
                result: null,
                error: 'Job not found',
                timing: { created: null, started: null, finished: null, durationMs: null }
            });
        }

        const started = data.started_at ? new Date(data.started_at).getTime() : null;
        const finished = data.finished_at ? new Date(data.finished_at).getTime() : null;

        return res.json({
            jobId: data.id,
            status: data.status,
            result: data.status === 'done' ? data.result : null,
            error: data.status === 'error' ? data.error : null,
            timing: {
                created: data.created_at || null,
                started: data.started_at || null,
                finished: data.finished_at || null,
                durationMs: started && finished ? Math.max(0, finished - started) : null
            }
        });
    } catch (error) {
        return res.status(500).json({
            jobId: req.params.id,
            status: 'error',
            result: null,
            error: error.message,
            timing: { created: null, started: null, finished: null, durationMs: null }
        });
    }
});


